-- 20260712003_scope_vocabulary_standardization.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 003: Standardize scope vocabulary to personal | lab | project across all features.
-- Canonical set: ('personal', 'lab', 'project') — no more 'my'.
--
-- Live tables affected:
--   reminders.scope — CHECK was ('personal', 'lab'), expand to include 'project'
--   literature_items.library — no CHECK existed on the live column; add one now
--                              + update any 'my' rows to 'personal' (safe no-op; 0 rows)
--
-- Tables added by migration 002 (tasks, bookmarks, schedule_events) already have
-- the expanded constraint written in migration 002 — no action needed here.

-- ── reminders.scope ───────────────────────────────────────────────────────────
-- Drop any existing CHECK constraint on reminders.scope (name may vary),
-- then add the expanded constraint.

do $$
declare
  cname text;
begin
  select con.conname into cname
  from pg_constraint con
  join pg_class rel on rel.oid = con.conrelid
  join pg_namespace ns on ns.oid = rel.relnamespace
  where rel.relname = 'reminders'
    and ns.nspname = 'public'
    and con.contype = 'c'
    and con.conname ilike '%scope%';

  if cname is not null then
    execute 'alter table reminders drop constraint ' || quote_ident(cname);
  end if;
end $$;

alter table reminders
  add constraint reminders_scope_check
    check (scope in ('personal', 'lab', 'project'));

-- ── literature_items.library ──────────────────────────────────────────────────
-- The live DB column is `library` (not `scope`) with no CHECK constraint.
-- First migrate any stale 'my' values (0 rows currently; included for safety).
-- Then add the canonical CHECK constraint.

update literature_items
  set library = 'personal'
  where library = 'my';

do $$
declare
  cname text;
begin
  select con.conname into cname
  from pg_constraint con
  join pg_class rel on rel.oid = con.conrelid
  join pg_namespace ns on ns.oid = rel.relnamespace
  where rel.relname = 'literature_items'
    and ns.nspname = 'public'
    and con.contype = 'c'
    and con.conname ilike '%library%';

  if cname is not null then
    execute 'alter table literature_items drop constraint ' || quote_ident(cname);
  end if;
end $$;

alter table literature_items
  add constraint literature_items_library_check
    check (library in ('lab', 'personal', 'project'));

-- ════════════════════════════════════════════════════════════════════════════
-- 20260712004_external_project_members.sql
-- ════════════════════════════════════════════════════════════════════════════
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
-- Migration: external project members + access-control
-- Adds: invited_email drift fix, sub_project_invite_codes table,
--       sub_project_members schema additions, literature_items sub_project_id,
--       and 12 additive RLS policy updates.
-- Safe to run on production: additive only; DROP POLICY IF EXISTS before each
-- recreate; IF NOT EXISTS on all DDL; no data destructive operations.
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

-- ── 1. Drift fix: invite_codes.invited_email ──────────────────────────────────
-- Column exists in the live DB but was missing from schema.sql. This is a no-op
-- on production.
alter table invite_codes
  add column if not exists invited_email text;

-- ── 2. New table: sub_project_invite_codes ────────────────────────────────────
-- Mirrors invite_codes but scoped to a sub_project rather than the lab.
-- Used for project-level invites by email, including external (non-lab) users.
create table if not exists sub_project_invite_codes (
  id             uuid        primary key default gen_random_uuid(),
  token          text        not null unique,
  sub_project_id uuid        not null references sub_projects(id) on delete cascade,
  invited_email  text        not null,
  invited_by     uuid        not null references auth.users(id),
  status         text        not null check (status in ('pending','accepted','expired')) default 'pending',
  used_by        uuid        references auth.users(id),
  used_at        timestamptz,
  created_at     timestamptz not null default now()
);

alter table sub_project_invite_codes enable row level security;

-- Anyone can look up a token (needed for acceptance flow before/just after auth,
-- mirrors invite_codes policy "anyone can look up a code").
drop policy if exists "anyone can look up a project invite" on sub_project_invite_codes;
create policy "anyone can look up a project invite" on sub_project_invite_codes
  for select using (true);

-- Only the inviter may create a row (mirrors "pi can insert invite code").
drop policy if exists "inviter can insert project invite" on sub_project_invite_codes;
create policy "inviter can insert project invite" on sub_project_invite_codes
  for insert with check (auth.uid() = invited_by);

-- Acceptance: mark status → 'accepted' and record used_by; only while pending
-- (mirrors "user can claim unused code").
drop policy if exists "user can claim pending project invite" on sub_project_invite_codes;
create policy "user can claim pending project invite" on sub_project_invite_codes
  for update using (status = 'pending') with check (auth.uid() = used_by);

-- Inviter may also expire/cancel their own invites.
drop policy if exists "inviter can update own project invite" on sub_project_invite_codes;
create policy "inviter can update own project invite" on sub_project_invite_codes
  for update using (auth.uid() = invited_by);

-- ── 3. Schema additions ───────────────────────────────────────────────────────

-- sub_project_members: audit columns for invite tracking.
alter table sub_project_members
  add column if not exists joined_at  timestamptz not null default now(),
  add column if not exists invited_by uuid        references auth.users(id) on delete set null;

-- literature_items: FK so project-scoped items can be filtered per sub_project
-- (required for future external-member RLS on literature).
alter table literature_items
  add column if not exists sub_project_id uuid references sub_projects(id) on delete set null;

-- ── 4. RLS policy updates ─────────────────────────────────────────────────────
-- Convention: the EXISTING predicate is reproduced verbatim as the first branch;
-- the NEW branch is clearly marked and added with OR.

-- ── (1) sub_projects SELECT ───────────────────────────────────────────────────
-- External members can see the sub_project they belong to (needed so they can
-- load their project context on login). Lab-scoped rows NOT exposed.
drop policy if exists "lab members can read sub_projects" on sub_projects;
create policy "lab members can read sub_projects" on sub_projects
  for select using (
    -- EXISTING: lab members see all sub_projects in their lab
    exists (
      select 1 from team_members tm
      where tm.project_id = sub_projects.project_id and tm.user_id = auth.uid()
    )
    -- NEW: external member sees only the sub_projects they belong to
    or exists (
      select 1 from sub_project_members spm
      where spm.sub_project_id = sub_projects.id and spm.user_id = auth.uid()
    )
  );

-- ── (2) sub_project_members SELECT ───────────────────────────────────────────
-- Allows external members to read their own membership row, which the existing
-- FOR ALL policy already grants via user_id = auth.uid(). Extending the named
-- SELECT policy here makes it explicit and self-documenting.
drop policy if exists "lab members can read sub_project_members" on sub_project_members;
create policy "lab members can read sub_project_members" on sub_project_members
  for select using (
    -- EXISTING: lab members see all membership rows for their lab's sub_projects
    exists (
      select 1 from sub_projects sp
      join team_members tm on tm.project_id = sp.project_id
      where sp.id = sub_project_members.sub_project_id and tm.user_id = auth.uid()
    )
    -- NEW: any member (including external) can read their own row
    or user_id = auth.uid()
  );

-- ── (3) sub_project_members INSERT (privileged) ───────────────────────────────
-- PI (projects.owner_id) or sub_project creator may add any user_id.
-- Self-insert (accepting an invite) is already covered by the existing FOR ALL
-- policy "lab members can manage own sub_project membership".
drop policy if exists "privileged can insert sub_project_members" on sub_project_members;
create policy "privileged can insert sub_project_members" on sub_project_members
  for insert with check (
    exists (
      select 1 from sub_projects sp
      join projects p on p.id = sp.project_id
      where sp.id = sub_project_members.sub_project_id
        and (p.owner_id = auth.uid() or sp.created_by = auth.uid())
    )
  );

-- ── (4) sub_project_members DELETE (privileged) ───────────────────────────────
-- PI or sub_project creator may remove any member from their sub_project.
-- Self-removal is already covered by the existing FOR ALL policy.
drop policy if exists "privileged can delete sub_project_members" on sub_project_members;
create policy "privileged can delete sub_project_members" on sub_project_members
  for delete using (
    exists (
      select 1 from sub_projects sp
      join projects p on p.id = sp.project_id
      where sp.id = sub_project_members.sub_project_id
        and (p.owner_id = auth.uid() or sp.created_by = auth.uid())
    )
  );

-- ── (5) tasks SELECT ──────────────────────────────────────────────────────────
-- External project member can read tasks scoped to their sub_project.
-- Lab-scoped and personal tasks remain invisible to them (no team_members row).
drop policy if exists "project members can read tasks" on tasks;
create policy "project members can read tasks" on tasks
  for select using (
    -- EXISTING: lab members read all tasks in their lab project
    exists (
      select 1 from team_members tm
      where tm.project_id = tasks.project_id and tm.user_id = auth.uid()
    )
    -- NEW: external member reads only project-scoped tasks in their sub_project
    or (
      tasks.scope = 'project'
      and tasks.sub_project_id is not null
      and exists (
        select 1 from sub_project_members spm
        where spm.sub_project_id = tasks.sub_project_id and spm.user_id = auth.uid()
      )
    )
  );

-- ── (6) tasks INSERT ──────────────────────────────────────────────────────────
drop policy if exists "project members can insert tasks" on tasks;
create policy "project members can insert tasks" on tasks
  for insert with check (
    auth.uid() = created_by and (
      -- EXISTING
      exists (
        select 1 from team_members tm
        where tm.project_id = tasks.project_id and tm.user_id = auth.uid()
      )
      -- NEW
      or (
        tasks.scope = 'project'
        and tasks.sub_project_id is not null
        and exists (
          select 1 from sub_project_members spm
          where spm.sub_project_id = tasks.sub_project_id and spm.user_id = auth.uid()
        )
      )
    )
  );

-- ── (7) bookmarks SELECT ──────────────────────────────────────────────────────
drop policy if exists "project members can read bookmarks" on bookmarks;
create policy "project members can read bookmarks" on bookmarks
  for select using (
    -- EXISTING
    exists (
      select 1 from team_members tm
      where tm.project_id = bookmarks.project_id and tm.user_id = auth.uid()
    )
    -- NEW
    or (
      bookmarks.scope = 'project'
      and bookmarks.sub_project_id is not null
      and exists (
        select 1 from sub_project_members spm
        where spm.sub_project_id = bookmarks.sub_project_id and spm.user_id = auth.uid()
      )
    )
  );

-- ── (8) bookmarks INSERT ──────────────────────────────────────────────────────
drop policy if exists "project members can insert bookmarks" on bookmarks;
create policy "project members can insert bookmarks" on bookmarks
  for insert with check (
    -- EXISTING
    exists (
      select 1 from team_members tm
      where tm.project_id = bookmarks.project_id and tm.user_id = auth.uid()
    )
    -- NEW
    or (
      bookmarks.scope = 'project'
      and bookmarks.sub_project_id is not null
      and exists (
        select 1 from sub_project_members spm
        where spm.sub_project_id = bookmarks.sub_project_id and spm.user_id = auth.uid()
      )
    )
  );

-- ── (9) schedule_events SELECT ────────────────────────────────────────────────
-- Adds the missing scope='project' branch (Phase 3 added project events to the
-- DB but the old SELECT policy had no predicate for them — they fell through).
drop policy if exists "members can read lab events and own personal events" on schedule_events;
create policy "members can read lab events and own personal events" on schedule_events
  for select using (
    -- EXISTING: lab scope — lab members only
    (scope = 'lab' and exists (
      select 1 from team_members tm
      where tm.project_id = schedule_events.project_id and tm.user_id = auth.uid()
    ))
    -- EXISTING: personal scope — creator only
    or (scope = 'personal' and auth.uid() = created_by)
    -- NEW: project scope — sub_project members (including external)
    or (
      scope = 'project'
      and schedule_events.sub_project_id is not null
      and exists (
        select 1 from sub_project_members spm
        where spm.sub_project_id = schedule_events.sub_project_id and spm.user_id = auth.uid()
      )
    )
  );

-- ── (10) schedule_events INSERT ───────────────────────────────────────────────
drop policy if exists "project members can insert events" on schedule_events;
create policy "project members can insert events" on schedule_events
  for insert with check (
    auth.uid() = created_by and (
      -- EXISTING
      exists (
        select 1 from team_members tm
        where tm.project_id = schedule_events.project_id and tm.user_id = auth.uid()
      )
      -- NEW
      or (
        schedule_events.scope = 'project'
        and schedule_events.sub_project_id is not null
        and exists (
          select 1 from sub_project_members spm
          where spm.sub_project_id = schedule_events.sub_project_id and spm.user_id = auth.uid()
        )
      )
    )
  );

-- ── (11) reminders SELECT ─────────────────────────────────────────────────────
-- Adds a project-scope branch. Lab-scoped reminders remain gated on team_members.
drop policy if exists "reminders select" on reminders;
create policy "reminders select" on reminders
  for select using (
    -- EXISTING: own reminders (personal scope)
    auth.uid() = user_id
    -- EXISTING: lab-scoped reminders visible to all lab members
    or (scope = 'lab' and exists (
      select 1 from team_members tm
      where tm.project_id = reminders.project_id and tm.user_id = auth.uid()
    ))
    -- NEW: project-scoped reminders visible to sub_project members only
    or (
      scope = 'project'
      and reminders.sub_project_id is not null
      and exists (
        select 1 from sub_project_members spm
        where spm.sub_project_id = reminders.sub_project_id and spm.user_id = auth.uid()
      )
    )
  );

-- ── (12) user_profiles SELECT: co-sub_project members ────────────────────────
-- External members can read profiles of people who share at least one
-- sub_project with them. This does NOT expose the full lab roster: the join only
-- matches users who are in a common sub_project_members row.
-- Added as a third SELECT policy (additive; existing policies untouched).
drop policy if exists "sub-project co-members can read profiles" on user_profiles;
create policy "sub-project co-members can read profiles" on user_profiles
  for select using (
    exists (
      select 1
      from   sub_project_members a
      join   sub_project_members b on b.sub_project_id = a.sub_project_id
      where  a.user_id = auth.uid()
        and  b.user_id = user_profiles.id
    )
  );

-- ════════════════════════════════════════════════════════════════════════════
-- 20260712005_literature_rls_external.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 005: Literature RLS — additive OR-branch for sub-project members
-- Mirrors the tasks/bookmarks pattern from migration 004.
-- Never drops lab-member access; only adds the external-member path.

-- ── Ensure added_by exists (live DB may pre-date this column) ────────────────
alter table literature_items
  add column if not exists added_by uuid references auth.users(id);

-- ── literature_items SELECT ──────────────────────────────────────────────────
drop policy if exists "project members can read literature" on literature_items;
create policy "project members can read literature" on literature_items
  for select using (
    -- existing: lab member
    exists (select 1 from team_members tm where tm.project_id = literature_items.project_id and tm.user_id = auth.uid())
    or
    -- new: sub-project member reading project-scoped items for their sub-project
    (
      literature_items.sub_project_id is not null
      and exists (
        select 1 from sub_project_members spm
        where spm.sub_project_id = literature_items.sub_project_id
          and spm.user_id = auth.uid()
      )
    )
  );

-- ── literature_items ALL (manage) ────────────────────────────────────────────
drop policy if exists "project members can manage literature" on literature_items;
create policy "project members can manage literature" on literature_items
  for all using (
    -- existing: lab member
    exists (select 1 from team_members tm where tm.project_id = literature_items.project_id and tm.user_id = auth.uid())
    or
    -- new: sub-project member managing project-scoped items for their sub-project
    (
      literature_items.sub_project_id is not null
      and exists (
        select 1 from sub_project_members spm
        where spm.sub_project_id = literature_items.sub_project_id
          and spm.user_id = auth.uid()
      )
    )
  ) with check (
    auth.uid() = added_by
  );

-- ════════════════════════════════════════════════════════════════════════════
-- 20260712006_fix_rls_recursion_and_avatar_url.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 006: Fix RLS infinite recursion on user_profiles + add avatar_url
--
-- ROOT CAUSE (500s):
--   "sub-project co-members can read profiles" (user_profiles SELECT) queries
--   sub_project_members, whose own SELECT policy queries team_members, which
--   PostgREST resolves via the FK join back to user_profiles — infinite loop.
--
-- FIX: Replace the inline sub_project_members subquery with a SECURITY DEFINER
--   helper function. SECURITY DEFINER runs as the function owner (bypasses RLS),
--   so the co-member check never re-enters user_profiles policies.
--
-- ROOT CAUSE (400s): avatar_url column missing from user_profiles.

-- ── 1. Add avatar_url ─────────────────────────────────────────────────────────
alter table user_profiles
  add column if not exists avatar_url text;

-- ── 2. SECURITY DEFINER helper — checks sub-project co-membership ─────────────
-- Runs as the definer (bypasses RLS), so it reads sub_project_members directly
-- without triggering sub_project_members' SELECT policy, which would re-enter
-- user_profiles and recurse.
create or replace function auth_uid_shares_sub_project(profile_user_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1
    from   sub_project_members a
    join   sub_project_members b on b.sub_project_id = a.sub_project_id
    where  a.user_id = auth.uid()
      and  b.user_id = profile_user_id
  );
$$;

-- ── 3. Rewrite the recursive policy to use the helper ─────────────────────────
drop policy if exists "sub-project co-members can read profiles" on user_profiles;
create policy "sub-project co-members can read profiles" on user_profiles
  for select using (
    auth_uid_shares_sub_project(user_profiles.id)
  );

-- ════════════════════════════════════════════════════════════════════════════
-- 20260712007_fix_subprojects_recursion.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 007: Fix mutual RLS recursion between sub_projects and sub_project_members
--
-- ROOT CAUSE:
--   sub_projects SELECT policy  → queries sub_project_members (line 83-86 of 004)
--   sub_project_members SELECT policy → queries sub_projects  (line 97-101 of 004)
--   Postgres evaluates both with RLS active → infinite recursion → 500 on any
--   query that touches either table (including ProjectContext's sub_project_members
--   fetch and any team_members join that joins sub_projects).
--
-- FIX: Wrap the sub_project_members lookup inside the sub_projects SELECT policy
--   in a SECURITY DEFINER function. SECURITY DEFINER bypasses RLS on
--   sub_project_members, so that branch never re-enters sub_projects' policy.
--   The sub_project_members policy's sub_projects join is now safe because
--   sub_projects' policy no longer recurses back into sub_project_members.

-- ── SECURITY DEFINER helper ───────────────────────────────────────────────────
create or replace function auth_uid_is_sub_project_member(p_sub_project_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from sub_project_members spm
    where spm.sub_project_id = p_sub_project_id
      and spm.user_id = auth.uid()
  );
$$;

-- ── Rewrite sub_projects SELECT to use the helper ─────────────────────────────
drop policy if exists "lab members can read sub_projects" on sub_projects;
create policy "lab members can read sub_projects" on sub_projects
  for select using (
    -- existing: lab members see all sub_projects in their lab
    exists (
      select 1 from team_members tm
      where tm.project_id = sub_projects.project_id and tm.user_id = auth.uid()
    )
    -- new: external member sees only the sub_projects they belong to
    -- (SECURITY DEFINER — does not trigger sub_project_members RLS → no recursion)
    or auth_uid_is_sub_project_member(sub_projects.id)
  );

-- ════════════════════════════════════════════════════════════════════════════
-- 20260714008_color_and_subtasks.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 008: sub_projects.color + tasks.parent_id
--
-- Item 9: Material color palette per sub-project (assigned at creation time by the UI).
-- Item 13: Subtasks — parent_id is a self-FK; null = top-level task.
--          Subtasks inherit scope/project_id/sub_project_id from their parent.

alter table sub_projects
  add column if not exists color text;

alter table tasks
  add column if not exists parent_id uuid references tasks(id) on delete cascade;

-- ════════════════════════════════════════════════════════════════════════════
-- 20260727009_literature_soft_delete.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 009: Soft-delete columns for literature_items
-- Required for the "Recently removed" feature in the Literature module.
-- Without these columns every SELECT against literature_items returns HTTP 400
-- because the app code filters on deleted_at which does not exist yet.
--
-- Safe to run multiple times (all statements are IF NOT EXISTS / OR REPLACE).

alter table literature_items
  add column if not exists deleted_at  timestamptz,
  add column if not exists deleted_by  uuid references auth.users(id);

-- Efficient index for the "Recently removed" query which orders by deleted_at DESC
-- and filters WHERE deleted_at IS NOT NULL.
create index if not exists literature_items_deleted_at_idx
  on literature_items (project_id, deleted_at)
  where deleted_at is not null;

-- No RLS changes needed: the existing "project members can manage literature"
-- policy (for all) already allows lab members to UPDATE a row's deleted_at back
-- to NULL (restore) and to SELECT soft-deleted rows for the trash view.
-- Soft-deleted rows remain readable by the owner's lab — that is intentional so
-- the "Recently removed" panel can list and restore them.

-- ════════════════════════════════════════════════════════════════════════════
-- 20260727010_fix_literature_manage_check.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 010: Fix literature_items manage policy WITH CHECK
-- The previous policy required added_by = auth.uid() but added_by was never
-- set by app-level inserts, so all inserts and updates were silently rejected.
-- This migration:
--   1. Backfills added_by = user_id for existing rows where added_by is null
--   2. Changes WITH CHECK to accept either added_by or user_id as ownership proof

update literature_items
  set added_by = user_id
  where added_by is null and user_id is not null;

drop policy if exists "project members can manage literature" on literature_items;
create policy "project members can manage literature" on literature_items
  for all using (
    exists (
      select 1 from team_members tm
      where tm.project_id = literature_items.project_id
        and tm.user_id = auth.uid()
    )
    or
    (
      literature_items.sub_project_id is not null
      and exists (
        select 1 from sub_project_members spm
        where spm.sub_project_id = literature_items.sub_project_id
          and spm.user_id = auth.uid()
      )
    )
  ) with check (
    auth.uid() = coalesce(added_by, user_id)
  );

-- ════════════════════════════════════════════════════════════════════════════
-- 20260728011_bookmarks_member_delete.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 011: Allow any lab/project member to delete shared bookmarks.
-- Personal bookmarks remain restricted to their creator.

drop policy if exists "adder can delete bookmarks" on bookmarks;

create policy "members can delete bookmarks" on bookmarks
  for delete using (
    -- Personal bookmarks: only the creator can delete
    (scope = 'personal' and added_by = auth.uid())
    -- Lab / project-scoped bookmarks: any project member can delete
    or (
      coalesce(scope, 'lab') != 'personal'
      and exists (
        select 1 from team_members tm
        where tm.project_id = bookmarks.project_id and tm.user_id = auth.uid()
      )
    )
  );

-- ════════════════════════════════════════════════════════════════════════════
-- 20260728012_literature_volume_pages.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 012: Add volume and pages columns to literature_items.
-- These were present on LiteratureItem in TypeScript but had no backing DB column,
-- so Zotero-imported volume/issue and page ranges were silently dropped.

alter table literature_items
  add column if not exists volume text,
  add column if not exists pages  text;

-- ════════════════════════════════════════════════════════════════════════════
-- 20260728013_bookmarks_rls_cleanup.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 013: Drop the stale bookmarks delete policy.
-- Migration 011 created "members can delete bookmarks" (the correct policy) but its
-- DROP used the wrong name ("adder can delete bookmarks") so the old restrictive policy
-- "Members can delete their own bookmarks" was never removed. Both policies are now
-- PERMISSIVE and the union of their USING clauses is correct, but the old one is
-- redundant. This migration drops it for clarity.

drop policy if exists "Members can delete their own bookmarks" on bookmarks;
drop policy if exists "adder can delete bookmarks" on bookmarks;

-- ════════════════════════════════════════════════════════════════════════════
-- 20260731014_literature_doi_unique.sql
-- ════════════════════════════════════════════════════════════════════════════
-- DB-level backstop against duplicate DOIs within a project.
-- A partial unique index (not a constraint) so NULL DOIs and soft-deleted rows are excluded.
-- If two items in the same project have the same DOI and are both active, the second insert/update
-- will fail at the DB level — this catches any case where the client-side dupe check is bypassed
-- (e.g. concurrent syncs, direct API writes, or stale snapshot misses).
--
-- IMPORTANT: Run this AFTER 20260728012_literature_volume_pages.sql has been applied.
-- If the index creation fails because duplicates already exist, identify them first with:
--   SELECT doi, project_id, COUNT(*) FROM literature_items
--   WHERE doi IS NOT NULL AND deleted_at IS NULL
--   GROUP BY doi, project_id HAVING COUNT(*) > 1;
-- Then merge or delete the extras, then re-run.

CREATE UNIQUE INDEX IF NOT EXISTS literature_items_project_doi_unique
  ON literature_items (project_id, doi)
  WHERE doi IS NOT NULL AND deleted_at IS NULL;

-- ════════════════════════════════════════════════════════════════════════════
-- 20260803015_activity_feed_sub_project.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Add sub_project_id to activity_feed so individual project dashboards can filter
-- the Team Activity widget to only show activity belonging to the selected sub-project.
--
-- Existing rows get sub_project_id = NULL, which is intentional: they are treated as
-- lab-wide activity and appear only in the Lab Home dashboard view. Project-specific
-- views will only show rows where sub_project_id matches the selected sub-project.
--
-- Run this migration before deploying the dashboard scoping changes.

ALTER TABLE activity_feed
  ADD COLUMN IF NOT EXISTS sub_project_id uuid REFERENCES sub_projects(id);

-- ════════════════════════════════════════════════════════════════════════════
-- 20260804016_deduplicate_literature.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 016: Clean up duplicate and inconsistent literature_items.
--
-- Problems observed in QA:
--   1. "Dynamics of algorithmic content amplification on TikTok" appears in both
--      active items (deleted_at IS NULL) AND recently-removed (deleted_at IS NOT NULL).
--      This happens when the same item was imported twice — once active, once deleted.
--      Keep the active (non-deleted) copy and hard-delete the deleted duplicate.
--   2. "Ideological fragmentation of the social media ecosystem" and
--      "A Picture is Worth a Thousand (S)words" are duplicated inside the trash itself.
--      Keep the most-recently-deleted copy and hard-delete the older one.
--
-- Safe to run multiple times (idempotent via WHERE EXISTS guards).

-- ── 1. Remove soft-deleted duplicates that have an active twin ────────────────
--
-- For every deleted row that shares (project_id, title) with a non-deleted row,
-- hard-delete the deleted row.
DELETE FROM literature_items
WHERE deleted_at IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM literature_items twin
    WHERE twin.project_id  = literature_items.project_id
      AND twin.title       = literature_items.title
      AND twin.deleted_at  IS NULL
  );

-- ── 2. De-duplicate within the trash itself ───────────────────────────────────
--
-- Keep the most-recently-deleted row; hard-delete older duplicates.
DELETE FROM literature_items
WHERE deleted_at IS NOT NULL
  AND id NOT IN (
    SELECT DISTINCT ON (project_id, title) id
    FROM literature_items
    WHERE deleted_at IS NOT NULL
    ORDER BY project_id, title, deleted_at DESC
  );

-- ════════════════════════════════════════════════════════════════════════════
-- 20260804017_literature_zotero_key.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 017: Add zotero_key column for stable per-item deduplication.
--
-- Problem: literature_items has a partial unique index on (project_id, doi)
-- WHERE doi IS NOT NULL.  Items without a DOI have no dedup key at all — every
-- re-sync of a Zotero collection creates fresh duplicate rows for those items
-- regardless of how many times they already exist in the DB.
--
-- Fix: add a stable Zotero item key (8-char alphanumeric, e.g. "AIXIUGN3")
-- stored as zotero_key.  A unique partial index prevents inserting the same
-- Zotero item twice into the same project, even when doi IS NULL.
--
-- Idempotent: IF NOT EXISTS guards let this run multiple times safely.

-- ── 1. Add the column ─────────────────────────────────────────────────────────
ALTER TABLE literature_items
  ADD COLUMN IF NOT EXISTS zotero_key varchar(32) DEFAULT NULL;

-- ── 2. Unique partial index ────────────────────────────────────────────────────
-- Scoped to project, active rows only.  NULL values are excluded so non-Zotero
-- items (manual adds, BibTeX, DOI lookup) are unaffected.
CREATE UNIQUE INDEX IF NOT EXISTS literature_items_project_zotero_key_unique
  ON literature_items (project_id, zotero_key)
  WHERE zotero_key IS NOT NULL AND deleted_at IS NULL;

-- ── 3. Backfill hint (cannot be automated — run after deploying the app code) ─
-- Once the app populates zotero_key on new syncs you can optionally backfill
-- existing rows via the Zotero API, but that requires user credentials.
-- The new unique index prevents future duplicates without a backfill;
-- existing duplicate rows can be cleaned up separately (see migration 016).

-- ════════════════════════════════════════════════════════════════════════════
-- 20260804018_lit_annotations_zotero_key.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 018: Add zotero_key to lit_annotations for idempotent re-sync.
--
-- When Zotero annotations are re-imported on a subsequent sync of the same
-- collection, they must upsert rather than create duplicates. The Zotero
-- annotation key (e.g. "K3QMXR7P") is stable for the lifetime of the
-- annotation item and makes a reliable dedup key.
--
-- NULL zotero_key means the annotation was created manually inside Canopy and
-- is unaffected by the unique constraint.

ALTER TABLE lit_annotations
  ADD COLUMN IF NOT EXISTS zotero_key varchar(128) DEFAULT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS lit_annotations_item_zotero_key_unique
  ON lit_annotations (item_id, zotero_key)
  WHERE zotero_key IS NOT NULL;

-- ════════════════════════════════════════════════════════════════════════════
-- 20260804019_lit_annotations_color.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 019: Add color column to lit_annotations.
--
-- lit_annotations was created before migrations were tracked here.
-- The color column stores a CSS hex string (e.g. "#FBBF24") matching Canopy's
-- five highlight colors. NULL means no color tag (plain comment or highlight
-- with no color assignment).
--
-- Idempotent: IF NOT EXISTS lets this run safely more than once.

ALTER TABLE lit_annotations
  ADD COLUMN IF NOT EXISTS color varchar(32) DEFAULT NULL;

-- ════════════════════════════════════════════════════════════════════════════
-- 20260804020_fix_annotations_unique_index.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 020: Replace partial unique index on lit_annotations with a full one.
--
-- Problem: the partial index from migration 018 —
--   CREATE UNIQUE INDEX ... ON lit_annotations (item_id, zotero_key)
--   WHERE zotero_key IS NOT NULL
-- — cannot be used as an ON CONFLICT target by Supabase's JS client because
-- there is no way to pass the matching WHERE clause through .upsert().
-- Every upsert call therefore fails with "there is no unique or exclusion
-- constraint matching the ON CONFLICT specification" and falls through to the
-- plain-insert fallback, which produces duplicate rows on re-sync.
--
-- Fix: drop and recreate as a non-partial index. This is safe because PostgreSQL
-- unique indexes never treat NULL as equal to NULL, so rows with zotero_key IS NULL
-- continue to coexist freely — the uniqueness guarantee only applies to non-NULL
-- pairs of (item_id, zotero_key).
--
-- Cleanup: delete any annotation rows that were inserted via the fallback path
-- (zotero_key IS NULL, page_number IS NOT NULL, parent item has a zotero_key).
-- These are orphaned Zotero annotations with no stable key; they would become
-- duplicates on the next re-sync once the upsert path works correctly.
-- Manually-created annotations are NOT affected — they never have page_number set.

BEGIN;

DROP INDEX IF EXISTS lit_annotations_item_zotero_key_unique;

CREATE UNIQUE INDEX lit_annotations_item_zotero_key_unique
  ON lit_annotations (item_id, zotero_key);

-- Remove orphaned fallback-inserted Zotero annotation rows.
-- Criteria: no zotero_key + has a page_number (PDF-anchored → came from Zotero)
-- + parent item is a Zotero import (has zotero_key).
-- Manual annotations never have page_number set, so they are unaffected.
DELETE FROM lit_annotations
WHERE zotero_key IS NULL
  AND page_number IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM literature_items
    WHERE id = lit_annotations.item_id
      AND zotero_key IS NOT NULL
      AND deleted_at IS NULL
  );

COMMIT;

-- ════════════════════════════════════════════════════════════════════════════
-- 20260806021_user_settings.sql
-- ════════════════════════════════════════════════════════════════════════════
-- User-specific settings: timezone and per-day working hours
-- working_hours keys: "0"=Mon … "6"=Sun, value null = off day
-- Default: 9 AM–5 PM Monday–Friday, weekends off

CREATE TABLE IF NOT EXISTS user_settings (
  user_id      uuid PRIMARY KEY REFERENCES user_profiles(id) ON DELETE CASCADE,
  timezone     text NOT NULL DEFAULT 'America/New_York',
  working_hours jsonb NOT NULL DEFAULT '{
    "0": {"start": "09:00", "end": "17:00"},
    "1": {"start": "09:00", "end": "17:00"},
    "2": {"start": "09:00", "end": "17:00"},
    "3": {"start": "09:00", "end": "17:00"},
    "4": {"start": "09:00", "end": "17:00"},
    "5": null,
    "6": null
  }'::jsonb,
  updated_at   timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE user_settings ENABLE ROW LEVEL SECURITY;

-- Users can read/write only their own settings
DROP POLICY IF EXISTS "user_settings: owner select" ON user_settings;
CREATE POLICY "user_settings: owner select"
  ON user_settings FOR SELECT USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "user_settings: owner insert" ON user_settings;
CREATE POLICY "user_settings: owner insert"
  ON user_settings FOR INSERT WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "user_settings: owner update" ON user_settings;
CREATE POLICY "user_settings: owner update"
  ON user_settings FOR UPDATE USING (auth.uid() = user_id);

-- Team members of the same lab can read each other's settings (for scheduling)
DROP POLICY IF EXISTS "user_settings: team members select" ON user_settings;
CREATE POLICY "user_settings: team members select"
  ON user_settings FOR SELECT USING (
    EXISTS (
      SELECT 1 FROM team_members tm1
      JOIN team_members tm2 ON tm1.project_id = tm2.project_id
      WHERE tm1.user_id = auth.uid()
        AND tm2.user_id = user_settings.user_id
    )
  );

-- ════════════════════════════════════════════════════════════════════════════
-- 20260807022_tenant_isolation_fixes.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 022: Tenant isolation hardening
--
-- Findings from full RLS audit (2026-08-07):
--
-- HIGH:   invite_codes & sub_project_invite_codes have SELECT using(true)
--         → any authenticated user can enumerate all labs' invite codes + invited emails.
--
-- HIGH:   activity_feed table has no RLS at all (table predates tracked migrations;
--         migration 015 added a column but never enabled RLS).
--
-- HIGH:   notifications table has no RLS at all (same situation).
--
-- Fix strategy:
--   1. invite_codes — keep anonymous lookup by code value via SECURITY DEFINER RPC;
--      restrict direct table reads to own-lab members only.
--   2. sub_project_invite_codes — same approach.
--   3. activity_feed — enable RLS; project members see their lab's feed.
--   4. notifications — enable RLS; each user sees only their own notifications.
--
-- All statements are idempotent.

-- ── 1. invite_codes: restrict direct reads to own-lab members ─────────────────
--
-- Replace the "anyone can look up a code" SELECT policy with one that limits
-- direct table access to members of the same project. The join-flow (claiming a
-- code before you're a member) is handled exclusively via the RPC below.

DROP POLICY IF EXISTS "anyone can look up a code" ON invite_codes;
DROP POLICY IF EXISTS "lab members can read own invite codes" ON invite_codes;

CREATE POLICY "lab members can read own invite codes"
  ON invite_codes FOR SELECT USING (
    EXISTS (
      SELECT 1 FROM team_members tm
      WHERE tm.project_id = invite_codes.project_id
        AND tm.user_id = auth.uid()
    )
  );

-- SECURITY DEFINER RPC: returns only the fields needed for the join flow.
-- Callers who are not yet a team member (i.e., claiming an invite) use this
-- instead of a direct SELECT so we never expose the full codes table.
CREATE OR REPLACE FUNCTION claim_invite_code_lookup(p_code text)
RETURNS TABLE (
  project_id   uuid,
  invited_email text,
  used_by      uuid,
  used_at      timestamptz
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
  SELECT project_id, invited_email, used_by, used_at
  FROM   invite_codes
  WHERE  code = p_code
  LIMIT  1;
$$;

-- ── 2. sub_project_invite_codes: restrict direct reads ────────────────────────

DROP POLICY IF EXISTS "anyone can look up a project invite" ON sub_project_invite_codes;
DROP POLICY IF EXISTS "lab members can read own sub_project invite codes" ON sub_project_invite_codes;

CREATE POLICY "lab members can read own sub_project invite codes"
  ON sub_project_invite_codes FOR SELECT USING (
    -- inviter can always see their own tokens
    auth.uid() = invited_by
    -- lab members of the sub_project's parent project can read
    OR EXISTS (
      SELECT 1 FROM sub_projects sp
      JOIN   team_members tm ON tm.project_id = sp.project_id
      WHERE  sp.id = sub_project_invite_codes.sub_project_id
        AND  tm.user_id = auth.uid()
    )
  );

-- SECURITY DEFINER RPC for the external-invite claim flow
CREATE OR REPLACE FUNCTION claim_sub_project_invite_lookup(p_token text)
RETURNS TABLE (
  sub_project_id uuid,
  invited_email  text,
  status         text,
  used_by        uuid
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
  SELECT sub_project_id, invited_email, status, used_by
  FROM   sub_project_invite_codes
  WHERE  token = p_token
  LIMIT  1;
$$;

-- ── 3. activity_feed: enable RLS ─────────────────────────────────────────────
--
-- The table was created before migrations were tracked; RLS was never enabled.
-- Project members can read their own lab's feed; only authenticated users can
-- insert (the project_id check acts as the write guard).

ALTER TABLE activity_feed ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "project members can read activity feed" ON activity_feed;
CREATE POLICY "project members can read activity feed"
  ON activity_feed FOR SELECT USING (
    EXISTS (
      SELECT 1 FROM team_members tm
      WHERE tm.project_id = activity_feed.project_id
        AND tm.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "project members can insert activity feed" ON activity_feed;
CREATE POLICY "project members can insert activity feed"
  ON activity_feed FOR INSERT WITH CHECK (
    EXISTS (
      SELECT 1 FROM team_members tm
      WHERE tm.project_id = activity_feed.project_id
        AND tm.user_id = auth.uid()
    )
  );

-- ── 4. notifications: enable RLS ─────────────────────────────────────────────
--
-- Each user sees only notifications addressed to them.

ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "user reads own notifications" ON notifications;
CREATE POLICY "user reads own notifications"
  ON notifications FOR SELECT USING (
    auth.uid() = user_id
  );

DROP POLICY IF EXISTS "authenticated can insert notifications" ON notifications;
CREATE POLICY "authenticated can insert notifications"
  ON notifications FOR INSERT WITH CHECK (
    auth.uid() IS NOT NULL
  );

DROP POLICY IF EXISTS "user can mark own notifications read" ON notifications;
CREATE POLICY "user can mark own notifications read"
  ON notifications FOR UPDATE USING (
    auth.uid() = user_id
  );

DROP POLICY IF EXISTS "user can delete own notifications" ON notifications;
CREATE POLICY "user can delete own notifications"
  ON notifications FOR DELETE USING (
    auth.uid() = user_id
  );

-- ════════════════════════════════════════════════════════════════════════════
-- 20260816023_journal_entries_project_id.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Add project_id to journal_entries so entries can be scoped to a lab project.
-- This column has always been in schema.sql but was never applied as a migration.
-- After running this, PostgREST's schema cache must be reloaded so the column
-- becomes visible to the API (NOTIFY pgrst, 'reload schema' runs at the end).

alter table journal_entries
  add column if not exists project_id uuid references projects(id) on delete cascade;

-- Reload PostgREST schema cache so the new column is immediately visible.
notify pgrst, 'reload schema';

-- ════════════════════════════════════════════════════════════════════════════
-- 20260816024_projects_min_wellbeing_respondents.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Add configurable wellbeing respondent threshold to projects table.
-- Defaults to 4 (matches the prior hardcoded value), so existing labs are unaffected.
ALTER TABLE projects
  ADD COLUMN IF NOT EXISTS min_wellbeing_respondents integer NOT NULL DEFAULT 4;

-- Add per-user wellbeing opt-in to user_settings.
-- Defaults to true so all existing members are counted until they explicitly opt out.
ALTER TABLE user_settings
  ADD COLUMN IF NOT EXISTS wellbeing_opted_in boolean NOT NULL DEFAULT true;

-- ── get_wellbeing_rollup ──────────────────────────────────────────────────────
-- Returns weekly avg score per check-in question, only for weeks where at least
-- min_wellbeing_respondents distinct opted-in members submitted responses.
-- journal_entries.checkin is a JSONB array of {questionId, score} objects.
CREATE OR REPLACE FUNCTION get_wellbeing_rollup(p_project_id uuid)
RETURNS TABLE (
  week_start       date,
  question_id      text,
  avg_score        numeric,
  respondent_count bigint
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  WITH threshold AS (
    SELECT min_wellbeing_respondents AS t
    FROM   projects
    WHERE  id = p_project_id
  ),
  opted_in AS (
    SELECT us.user_id
    FROM   user_settings us
    JOIN   team_members  tm ON tm.user_id = us.user_id AND tm.project_id = p_project_id
    WHERE  us.wellbeing_opted_in = true
  ),
  responses AS (
    SELECT
      je.user_id,
      date_trunc('week', je.created_at)::date AS week_start,
      (elem->>'questionId')                   AS question_id,
      (elem->>'score')::numeric               AS score
    FROM journal_entries je
    JOIN opted_in oi ON oi.user_id = je.user_id
    CROSS JOIN LATERAL jsonb_array_elements(je.content->'checkin') AS elem
    WHERE je.project_id = p_project_id
      AND jsonb_array_length(je.content->'checkin') > 0
  ),
  weekly AS (
    SELECT
      week_start,
      question_id,
      AVG(score)             AS avg_score,
      COUNT(DISTINCT user_id) AS respondent_count
    FROM responses
    GROUP BY 1, 2
    HAVING COUNT(DISTINCT user_id) >= (SELECT t FROM threshold)
  )
  SELECT week_start, question_id, ROUND(avg_score, 2), respondent_count
  FROM   weekly
  ORDER  BY week_start, question_id;
$$;

-- ── get_overdue_signal ────────────────────────────────────────────────────────
-- Returns a single row: how many opted-in members have at least one overdue task,
-- and how many opted-in members exist total for this project.
CREATE OR REPLACE FUNCTION get_overdue_signal(p_project_id uuid)
RETURNS TABLE (
  overdue_count  bigint,
  total_members  bigint
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  WITH opted_in AS (
    SELECT us.user_id
    FROM   user_settings us
    JOIN   team_members  tm ON tm.user_id = us.user_id AND tm.project_id = p_project_id
    WHERE  us.wellbeing_opted_in = true
  ),
  overdue_members AS (
    SELECT DISTINCT ta.user_id
    FROM   tasks          t
    JOIN   task_assignees ta ON ta.task_id = t.id
    JOIN   opted_in       oi ON oi.user_id = ta.user_id
    WHERE  t.project_id = p_project_id
      AND  t.due_date   < CURRENT_DATE
      AND  t.status    != 'done'
      AND  (t.archived IS NULL OR t.archived = false)
  )
  SELECT
    (SELECT COUNT(*) FROM overdue_members) AS overdue_count,
    (SELECT COUNT(*) FROM opted_in)        AS total_members;
$$;

NOTIFY pgrst, 'reload schema';

-- ════════════════════════════════════════════════════════════════════════════
-- 20260821000_support_resources.sql
-- ════════════════════════════════════════════════════════════════════════════
-- support_invitation line on the lab (PI-authored, shown on the fork screen)
alter table projects
  add column if not exists support_invitation text;

-- ── support_resources ─────────────────────────────────────────────────────────
-- Stores lab-specific support contacts. "lab" = the projects row the lab maps to.
-- The prompt used the term "lab_id" but this schema uses project_id throughout.

create table if not exists support_resources (
  id              uuid primary key default gen_random_uuid(),
  project_id      uuid not null references projects(id) on delete cascade,
  label           text not null,
  description     text,
  confidentiality text,
  category        text not null check (category in ('urgent','counseling','academic','workplace','health','other')),
  contact_type    text not null check (contact_type in ('phone','url','email','in_person')),
  contact_value   text not null,
  availability    text,
  is_pinned       boolean not null default false,
  sort_order      int    not null default 0,
  active          boolean not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create or replace function _support_resources_set_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists trg_support_resources_updated_at on support_resources;
create trigger trg_support_resources_updated_at
  before update on support_resources
  for each row execute function _support_resources_set_updated_at();

alter table support_resources enable row level security;

-- Lab members see active resources for their lab
drop policy if exists "support_resources_member_select" on support_resources;
create policy "support_resources_member_select"
  on support_resources for select to authenticated
  using (
    active = true
    and exists (
      select 1 from team_members tm
      where tm.project_id = support_resources.project_id
        and tm.user_id = auth.uid()
    )
  );

-- PI/admin also see inactive rows (for the admin table)
drop policy if exists "support_resources_pi_select_all" on support_resources;
create policy "support_resources_pi_select_all"
  on support_resources for select to authenticated
  using (
    exists (
      select 1 from team_members tm
      where tm.project_id = support_resources.project_id
        and tm.user_id = auth.uid()
        and tm.role = 'pi'
    )
  );

drop policy if exists "support_resources_pi_insert" on support_resources;
create policy "support_resources_pi_insert"
  on support_resources for insert to authenticated
  with check (
    exists (
      select 1 from team_members tm
      where tm.project_id = project_id
        and tm.user_id = auth.uid()
        and tm.role = 'pi'
    )
  );

drop policy if exists "support_resources_pi_update" on support_resources;
create policy "support_resources_pi_update"
  on support_resources for update to authenticated
  using (
    exists (
      select 1 from team_members tm
      where tm.project_id = support_resources.project_id
        and tm.user_id = auth.uid()
        and tm.role = 'pi'
    )
  );

drop policy if exists "support_resources_pi_delete" on support_resources;
create policy "support_resources_pi_delete"
  on support_resources for delete to authenticated
  using (
    exists (
      select 1 from team_members tm
      where tm.project_id = support_resources.project_id
        and tm.user_id = auth.uid()
        and tm.role = 'pi'
    )
  );

notify pgrst, 'reload schema';

-- ════════════════════════════════════════════════════════════════════════════
-- 20260821001_chat_messages_schema.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 025: chat_messages full schema + missing columns
--
-- Diagnosis: chat_messages was created directly in the DB with a minimal schema
-- (id, channel, sender_id, content, created_at, thread_parent_id). The client
-- selects deleted_at, is_pinned, mentioned_user_ids, attachments, and
-- thread_last_replier_id — none of which exist, causing a 400 on every fetch.
--
-- This migration is idempotent: CREATE TABLE IF NOT EXISTS + ADD COLUMN IF NOT EXISTS.

-- ── chat_messages ─────────────────────────────────────────────────────────────

create table if not exists chat_messages (
  id                   uuid primary key default gen_random_uuid(),
  channel              text not null,
  sender_id            uuid not null references auth.users(id) on delete cascade,
  content              text not null default '',
  created_at           timestamptz not null default now(),
  thread_parent_id     uuid references chat_messages(id) on delete cascade,
  deleted_at           timestamptz,
  is_pinned            boolean not null default false,
  mentioned_user_ids   uuid[] not null default '{}',
  attachments          jsonb not null default '[]',
  thread_last_replier_id uuid references auth.users(id) on delete set null
);

-- Add missing columns to the existing table (no-ops if already present)
alter table chat_messages
  add column if not exists thread_parent_id     uuid references chat_messages(id) on delete cascade,
  add column if not exists deleted_at           timestamptz,
  add column if not exists is_pinned            boolean not null default false,
  add column if not exists mentioned_user_ids   uuid[] not null default '{}',
  add column if not exists attachments          jsonb not null default '[]',
  add column if not exists thread_last_replier_id uuid references auth.users(id) on delete set null;

-- Indexes already exist in DB; skipped to avoid false 42703 errors from Supabase.
-- chat_messages_channel_created_at: (channel, created_at)
-- chat_messages_thread_parent_id:   (thread_parent_id) WHERE thread_parent_id IS NOT NULL

alter table chat_messages enable row level security;

-- Lab members can read messages in channels they belong to.
-- Channel key format: lab:<project_id> | dm:<uid1>:<uid2> | project:<sub_project_id>
drop policy if exists "chat_messages_member_select" on chat_messages;
create policy "chat_messages_member_select"
  on chat_messages for select to authenticated
  using (
    -- lab channel: user is a lab member
    (channel like 'lab:%' and exists (
      select 1 from team_members tm
      where tm.project_id = regexp_replace(channel, '^lab:', '')::uuid
        and tm.user_id = auth.uid()
    ))
    -- dm channel: user is one of the two participants (uid sorted, colon-separated)
    or (channel like 'dm:%' and auth.uid()::text = any(string_to_array(
      regexp_replace(channel, '^dm:', ''), ':'
    )))
    -- project channel: user is a lab member of the parent project
    or (channel like 'project:%' and exists (
      select 1 from sub_projects sp
      join team_members tm on tm.project_id = sp.project_id
      where sp.id = regexp_replace(channel, '^project:', '')::uuid
        and tm.user_id = auth.uid()
    ))
  );

drop policy if exists "chat_messages_member_insert" on chat_messages;
create policy "chat_messages_member_insert"
  on chat_messages for insert to authenticated
  with check (
    sender_id = auth.uid()
    and (
      (channel like 'lab:%' and exists (
        select 1 from team_members tm
        where tm.project_id = regexp_replace(channel, '^lab:', '')::uuid
          and tm.user_id = auth.uid()
      ))
      or (channel like 'dm:%' and auth.uid()::text = any(string_to_array(
        regexp_replace(channel, '^dm:', ''), ':'
      )))
      or (channel like 'project:%' and exists (
        select 1 from sub_projects sp
        join team_members tm on tm.project_id = sp.project_id
        where sp.id = regexp_replace(channel, '^project:', '')::uuid
          and tm.user_id = auth.uid()
      ))
    )
  );

drop policy if exists "chat_messages_own_update" on chat_messages;
create policy "chat_messages_own_update"
  on chat_messages for update to authenticated
  using (sender_id = auth.uid() or exists (
    select 1 from team_members tm
    where tm.user_id = auth.uid() and tm.role = 'pi'
  ));

drop policy if exists "chat_messages_own_delete" on chat_messages;
create policy "chat_messages_own_delete"
  on chat_messages for delete to authenticated
  using (sender_id = auth.uid());

-- ── message_reactions ────────────────────────────────────────────────────────
-- One row per (message, user, emoji). Already exists in prod — safe IF NOT EXISTS.

create table if not exists message_reactions (
  message_id uuid not null references chat_messages(id) on delete cascade,
  user_id    uuid not null references auth.users(id) on delete cascade,
  emoji      text not null,
  primary key (message_id, user_id, emoji)
);

alter table message_reactions enable row level security;

drop policy if exists "message_reactions_select" on message_reactions;
create policy "message_reactions_select"
  on message_reactions for select to authenticated
  using (true);

drop policy if exists "message_reactions_insert" on message_reactions;
create policy "message_reactions_insert"
  on message_reactions for insert to authenticated
  with check (user_id = auth.uid());

drop policy if exists "message_reactions_delete" on message_reactions;
create policy "message_reactions_delete"
  on message_reactions for delete to authenticated
  using (user_id = auth.uid());

-- ── chat_read_state ───────────────────────────────────────────────────────────
-- Already exists in prod — safe IF NOT EXISTS.

create table if not exists chat_read_state (
  user_id     uuid not null references auth.users(id) on delete cascade,
  channel     text not null,
  last_read_at timestamptz not null default now(),
  primary key (user_id, channel)
);

alter table chat_read_state enable row level security;

drop policy if exists "chat_read_state_own" on chat_read_state;
create policy "chat_read_state_own"
  on chat_read_state for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

notify pgrst, 'reload schema';

