-- 20261016003_tabling.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 033: Tabling — shift slots, sign-ups and the after-slot log.
--
--   tabling_slots    VPs and the president create slots (optionally repeating
--                    weekly). Everyone in the LC sees them, including `taken`.
--   tabling_signups  members sign up / withdraw only through tabling_sign_up()
--                    and tabling_withdraw(), until the slot starts. Sign-up locks
--                    the slot row (SELECT … FOR UPDATE) so two people can never
--                    both take the last place. After the slot starts, its
--                    creator (or the president) marks attended / no-show and
--                    can add walk-ins. Only attended time counts as hours.
--   reminders        signing up creates a personal reminder due the day before;
--                    withdrawing (or the slot being deleted) removes it.

create table if not exists tabling_slots (
  id            uuid primary key default gen_random_uuid(),
  project_id    uuid not null references projects(id) on delete cascade,
  starts_at     timestamptz not null,
  ends_at       timestamptz not null,
  location      text not null check (length(trim(location)) > 0),
  purpose       text not null check (length(trim(purpose)) > 0),
  capacity      integer not null check (capacity between 1 and 50),
  taken         integer not null default 0,     -- maintained by trigger; non-walk-in sign-ups
  department_id uuid references departments(id) on delete set null,
  series_id     uuid,                           -- slots created together by "repeat weekly"
  created_by    uuid references user_profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  constraint tabling_slots_times check (ends_at > starts_at),
  constraint tabling_slots_not_overfull check (taken <= capacity)
);

create index if not exists tabling_slots_project_start_idx on tabling_slots (project_id, starts_at);

create table if not exists tabling_signups (
  slot_id      uuid not null references tabling_slots(id) on delete cascade,
  user_id      uuid not null references user_profiles(id) on delete cascade,
  project_id   uuid not null references projects(id) on delete cascade,
  status       text not null default 'signed_up' check (status in ('signed_up', 'attended', 'no_show')),
  walk_in      boolean not null default false,
  signed_up_at timestamptz not null default now(),
  marked_by    uuid references user_profiles(id) on delete set null,
  marked_at    timestamptz,
  primary key (slot_id, user_id)
);

create index if not exists tabling_signups_user_idx on tabling_signups (project_id, user_id);

-- ── Who may manage a slot: its creator (while still exec) or the president ──

create or replace function can_manage_tabling_slot(p_slot_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from tabling_slots s
    where s.id = p_slot_id
      and (is_lc_president(s.project_id) or (s.created_by = auth.uid() and is_lc_exec(s.project_id)))
  );
$$;

-- ── Keep `taken` in step with sign-ups; tidy reminders on removal ────────────

create or replace function _tabling_signups_changed()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'INSERT' and not new.walk_in then
    update tabling_slots set taken = taken + 1 where id = new.slot_id;  -- check constraint guards capacity
  elsif tg_op = 'DELETE' then
    if not old.walk_in then
      update tabling_slots set taken = greatest(taken - 1, 0) where id = old.slot_id;
    end if;
    delete from reminders
     where user_id = old.user_id and kind = 'tabling' and linked_event_id = old.slot_id;
  end if;
  return coalesce(new, old);
end;
$$;

drop trigger if exists trg_tabling_signups_changed on tabling_signups;
create trigger trg_tabling_signups_changed
  after insert or delete on tabling_signups
  for each row execute function _tabling_signups_changed();

create or replace function _tabling_slot_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.department_id is not null and not exists (
    select 1 from departments where id = new.department_id and project_id = new.project_id
  ) then
    raise exception 'Department does not belong to this LC';
  end if;
  if tg_op = 'UPDATE' and new.capacity < old.taken then
    raise exception 'Capacity can''t be lower than the % people already signed up', old.taken;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_tabling_slot_guard on tabling_slots;
create trigger trg_tabling_slot_guard
  before insert or update on tabling_slots
  for each row execute function _tabling_slot_guard();

-- ── Creating slots (with "repeat weekly until") ──────────────────────────────

create or replace function create_tabling_slots(
  p_project_id    uuid,
  p_starts_at     timestamptz,
  p_ends_at       timestamptz,
  p_location      text,
  p_purpose       text,
  p_capacity      integer,
  p_department_id uuid default null,
  p_repeat_until  date default null
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_series uuid := case when p_repeat_until is not null then gen_random_uuid() end;
  v_offset interval := interval '0';
  v_count  integer := 0;
begin
  if not is_lc_exec(p_project_id) then
    raise exception 'Only VPs and the president can create tabling slots';
  end if;
  if p_repeat_until is not null and p_repeat_until < p_starts_at::date then
    raise exception 'Repeat-until date is before the first slot';
  end if;

  loop
    insert into tabling_slots (project_id, starts_at, ends_at, location, purpose, capacity, department_id, series_id, created_by)
    values (p_project_id, p_starts_at + v_offset, p_ends_at + v_offset, trim(p_location), trim(p_purpose),
            p_capacity, p_department_id, v_series, auth.uid());
    v_count  := v_count + 1;
    v_offset := v_offset + interval '7 days';
    exit when p_repeat_until is null
           or (p_starts_at + v_offset)::date > p_repeat_until
           or v_count >= 52;   -- at most a year of weekly slots per call
  end loop;
  return v_count;
end;
$$;

-- ── Signing up and withdrawing ───────────────────────────────────────────────

create or replace function tabling_sign_up(p_slot_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_slot tabling_slots%rowtype;
begin
  -- Lock the slot so concurrent sign-ups for the last place run one at a time.
  select * into v_slot from tabling_slots where id = p_slot_id for update;
  if not found or not auth_is_project_member(v_slot.project_id) then
    raise exception 'Slot not found';
  end if;
  if v_slot.starts_at <= now() then
    raise exception 'This slot has already started';
  end if;
  if exists (select 1 from tabling_signups where slot_id = p_slot_id and user_id = auth.uid()) then
    return;  -- already signed up
  end if;
  if v_slot.taken >= v_slot.capacity then
    raise exception 'This slot is full';
  end if;

  insert into tabling_signups (slot_id, user_id, project_id) values (p_slot_id, auth.uid(), v_slot.project_id);

  insert into reminders (user_id, project_id, scope, title, due_at, kind, linked_event_id, email_enabled, sent, completed)
  values (auth.uid(), v_slot.project_id, 'personal',
          'Tabling tomorrow: ' || v_slot.purpose || ' (' || v_slot.location || ')',
          greatest(v_slot.starts_at - interval '1 day', now()),
          'tabling', p_slot_id, false, false, false);
end;
$$;

create or replace function tabling_withdraw(p_slot_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_slot tabling_slots%rowtype;
begin
  select * into v_slot from tabling_slots where id = p_slot_id for update;
  if not found then
    raise exception 'Slot not found';
  end if;
  if v_slot.starts_at <= now() then
    raise exception 'You can''t withdraw once the slot has started';
  end if;
  delete from tabling_signups where slot_id = p_slot_id and user_id = auth.uid() and not walk_in;
end;
$$;

-- ── After the slot: attended / no-show, walk-ins ─────────────────────────────

create or replace function tabling_mark(p_slot_id uuid, p_user_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_slot tabling_slots%rowtype;
begin
  select * into v_slot from tabling_slots where id = p_slot_id;
  if not found or not can_manage_tabling_slot(p_slot_id) then
    raise exception 'Only the slot''s creator or the president can mark attendance';
  end if;
  if v_slot.starts_at > now() then
    raise exception 'Attendance can be marked once the slot has started';
  end if;
  if p_status not in ('attended', 'no_show', 'signed_up') then
    raise exception 'Unknown status %', p_status;
  end if;

  update tabling_signups
     set status = p_status,
         marked_by = case when p_status = 'signed_up' then null else auth.uid() end,
         marked_at = case when p_status = 'signed_up' then null else now() end
   where slot_id = p_slot_id and user_id = p_user_id;
  if not found then
    raise exception 'That person did not sign up for this slot';
  end if;
end;
$$;

create or replace function tabling_add_walk_in(p_slot_id uuid, p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_slot tabling_slots%rowtype;
begin
  select * into v_slot from tabling_slots where id = p_slot_id;
  if not found or not can_manage_tabling_slot(p_slot_id) then
    raise exception 'Only the slot''s creator or the president can add walk-ins';
  end if;
  if v_slot.starts_at > now() then
    raise exception 'Walk-ins can be added once the slot has started';
  end if;
  if not exists (select 1 from team_members where project_id = v_slot.project_id and user_id = p_user_id) then
    raise exception 'Walk-ins must be members of this LC';
  end if;
  insert into tabling_signups (slot_id, user_id, project_id, status, walk_in, marked_by, marked_at)
  values (p_slot_id, p_user_id, v_slot.project_id, 'attended', true, auth.uid(), now())
  on conflict (slot_id, user_id) do update set status = 'attended', marked_by = auth.uid(), marked_at = now();
end;
$$;

revoke execute on function create_tabling_slots(uuid, timestamptz, timestamptz, text, text, integer, uuid, date) from public, anon;
revoke execute on function tabling_sign_up(uuid)             from public, anon;
revoke execute on function tabling_withdraw(uuid)            from public, anon;
revoke execute on function tabling_mark(uuid, uuid, text)    from public, anon;
revoke execute on function tabling_add_walk_in(uuid, uuid)   from public, anon;
grant  execute on function create_tabling_slots(uuid, timestamptz, timestamptz, text, text, integer, uuid, date) to authenticated;
grant  execute on function tabling_sign_up(uuid)             to authenticated;
grant  execute on function tabling_withdraw(uuid)            to authenticated;
grant  execute on function tabling_mark(uuid, uuid, text)    to authenticated;
grant  execute on function tabling_add_walk_in(uuid, uuid)   to authenticated;

-- ── Report: hours (attended only), no-shows and sign-ups per member ──────────
-- President: everyone. VP: members of departments they lead, plus themselves.
-- Member: only themselves.

create or replace function tabling_report(p_project_id uuid, p_from date default null, p_to date default null)
returns table (user_id uuid, hours numeric, attended integer, no_shows integer, upcoming integer)
language plpgsql
security definer
stable
set search_path = public
as $$
#variable_conflict use_column
declare
  v_role text := lc_role(p_project_id);
begin
  if v_role is null then
    return;
  end if;
  return query
  select su.user_id,
         round(coalesce(sum(extract(epoch from (s.ends_at - s.starts_at)) / 3600)
                         filter (where su.status = 'attended'), 0)::numeric, 2),
         (count(*) filter (where su.status = 'attended'))::integer,
         (count(*) filter (where su.status = 'no_show'))::integer,
         (count(*) filter (where su.status = 'signed_up' and s.starts_at > now()))::integer
  from   tabling_signups su
  join   tabling_slots s on s.id = su.slot_id
  where  su.project_id = p_project_id
    and  (p_from is null or s.starts_at::date >= p_from)
    and  (p_to   is null or s.starts_at::date <= p_to)
    and  (
           v_role = 'president'
        or su.user_id = auth.uid()
        or (v_role = 'vp' and in_led_department(p_project_id, su.user_id))
    )
  group  by su.user_id;
end;
$$;

revoke execute on function tabling_report(uuid, date, date) from public, anon;
grant  execute on function tabling_report(uuid, date, date) to authenticated;

-- ── RLS ───────────────────────────────────────────────────────────────────────

alter table tabling_slots   enable row level security;
alter table tabling_signups enable row level security;

drop policy if exists "lc members see tabling slots" on tabling_slots;
create policy "lc members see tabling slots" on tabling_slots
  for select using (auth_is_project_member(project_id));

drop policy if exists "creator or president edits slots" on tabling_slots;
create policy "creator or president edits slots" on tabling_slots
  for update using (can_manage_tabling_slot(id)) with check (is_lc_exec(project_id));

drop policy if exists "creator or president deletes slots" on tabling_slots;
create policy "creator or president deletes slots" on tabling_slots
  for delete using (can_manage_tabling_slot(id));

-- No insert policy: slots are created through create_tabling_slots().
-- No insert/update/delete policies on sign-ups: only the functions above write them.

drop policy if exists "sign-up visibility by role" on tabling_signups;
create policy "sign-up visibility by role" on tabling_signups
  for select using (
    user_id = auth.uid()
    or is_lc_president(project_id)
    or can_manage_tabling_slot(slot_id)
    or (is_lc_exec(project_id) and in_led_department(project_id, user_id))
  );

notify pgrst, 'reload schema';

-- ════════════════════════════════════════════════════════════════════════════
-- 20261017001_checkins_biweekly.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 034: Check-ins get their own table and a two-week cadence.
--
--   * checkins: one row per person, per LC, per check-in period. Owner-only RLS;
--     answers can be changed until the period ends. Journal entries no longer
--     carry scores (journal_entries.checkin_scores is kept for history).
--   * projects.checkin_period_weeks: 2 (default, every two weeks) or 1 (weekly).
--     Periods are anchored to Monday 2024-01-01 so every LC's fortnights line up
--     and never shift.
--   * Exec Pulse / Member Pulse now aggregate per period over the last 8 periods
--     (16 weeks at the default cadence). Same role checks, thresholds,
--     suppression and opt-out as migration 030.
--   * The check-in reminder is due on the Friday of each period's last week and
--     rolls forward one period when completed or when the check-in is submitted.

-- ── 1. Cadence ────────────────────────────────────────────────────────────────

alter table projects add column if not exists checkin_period_weeks integer not null default 2;
alter table projects drop constraint if exists projects_checkin_period_weeks_check;
alter table projects add constraint projects_checkin_period_weeks_check check (checkin_period_weeks in (1, 2));

-- First day (a Monday) of the check-in period containing p_at.
create or replace function checkin_period_start(p_project_id uuid, p_at timestamptz default now())
returns date
language sql
security definer
stable
set search_path = public
as $$
  with cfg as (
    select coalesce((select checkin_period_weeks from projects where id = p_project_id), 2) * 7 as days
  )
  select (date '2024-01-01'
          + (floor((date_trunc('week', p_at)::date - date '2024-01-01')::numeric / cfg.days) * cfg.days)::integer)
  from cfg;
$$;

-- ── 2. Check-ins ─────────────────────────────────────────────────────────────

create table if not exists checkins (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users(id) on delete cascade,
  project_id   uuid not null references projects(id) on delete cascade,
  period_start date not null,
  scores       jsonb not null check (jsonb_typeof(scores) = 'array' and jsonb_array_length(scores) > 0),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (user_id, project_id, period_start)
);

create index if not exists checkins_project_period_idx on checkins (project_id, period_start);

-- People record the current period only, and can edit it until it ends.
-- (Without an auth.uid() — service role, seed scripts — a given date is
-- normalised to its period, so history can be imported.)
create or replace function _checkins_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_current date := checkin_period_start(new.project_id, now());
begin
  if not exists (select 1 from team_members where project_id = new.project_id and user_id = new.user_id) then
    raise exception 'Check-ins are only for members of this LC';
  end if;
  if auth.uid() is not null then
    if tg_op = 'UPDATE' and old.period_start <> v_current then
      raise exception 'That check-in period has ended';
    end if;
    new.period_start := v_current;
  else
    new.period_start := checkin_period_start(new.project_id, coalesce(new.period_start::timestamptz, now()));
  end if;
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists trg_checkins_guard on checkins;
create trigger trg_checkins_guard
  before insert or update on checkins
  for each row execute function _checkins_guard();

alter table checkins enable row level security;

drop policy if exists "own check-ins only" on checkins;
create policy "own check-ins only" on checkins
  for all using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Copy existing journal check-ins (latest entry per person per period).
insert into checkins (user_id, project_id, period_start, scores, created_at)
select distinct on (je.user_id, je.project_id, checkin_period_start(je.project_id, je.created_at))
       je.user_id, je.project_id, checkin_period_start(je.project_id, je.created_at), je.checkin_scores, je.created_at
from   journal_entries je
join   team_members tm on tm.project_id = je.project_id and tm.user_id = je.user_id
where  je.project_id is not null
  and  jsonb_typeof(je.checkin_scores) = 'array'
  and  jsonb_array_length(je.checkin_scores) > 0
order  by je.user_id, je.project_id, checkin_period_start(je.project_id, je.created_at), je.created_at desc
on conflict (user_id, project_id, period_start) do nothing;

-- ── 3. Pulse functions on periods ────────────────────────────────────────────
-- Return columns change (week_start → period_start), so drop and recreate.

drop function if exists get_member_pulse(uuid, uuid);
drop function if exists get_exec_pulse(uuid);
drop function if exists _pulse_scores(uuid, text, integer);

create function _pulse_scores(p_project_id uuid, p_role text, p_periods integer)
returns table (user_id uuid, department_id uuid, period_start date, question_id text, score numeric)
language sql
security definer
stable
set search_path = public
as $$
  with population as (
    select tm.user_id, tm.department_id
    from   team_members tm
    left join user_settings us on us.user_id = tm.user_id
    where  tm.project_id = p_project_id
      and  tm.role = p_role
      and  coalesce(us.wellbeing_opted_in, true)
  ),
  cfg as (
    select coalesce(checkin_disabled_questions, '{}') as disabled,
           checkin_period_weeks * 7 as days
    from   projects where id = p_project_id
  )
  select c.user_id,
         pop.department_id,
         c.period_start,
         elem->>'questionId',
         avg((elem->>'score')::numeric)
  from   checkins c
  join   population pop on pop.user_id = c.user_id
  cross join cfg
  cross join lateral jsonb_array_elements(c.scores) as elem
  where  c.project_id = p_project_id
    and  c.period_start >= checkin_period_start(p_project_id, now()) - (p_periods - 1) * cfg.days
    and  (elem->>'score') ~ '^[1-5]$'
    and  not ((elem->>'questionId') = any (cfg.disabled))
  group  by 1, 2, 3, 4;
$$;

revoke execute on function _pulse_scores(uuid, text, integer) from public, anon, authenticated;

create function get_member_pulse(p_project_id uuid, p_department_id uuid default null)
returns table (
  department_id    uuid,
  period_start     date,
  question_id      text,
  avg_score        numeric,
  respondent_count integer,
  suppressed       boolean
)
language plpgsql
security definer
stable
set search_path = public
as $$
#variable_conflict use_column
declare
  v_role          text := lc_role(p_project_id);
  v_min           integer;
  v_days          integer;
  v_allowed       uuid[];
  v_include_total boolean;
begin
  if v_role = 'president' then
    select array_agg(d.id) into v_allowed from departments d where d.project_id = p_project_id;
    v_include_total := p_department_id is null;
  elsif v_role = 'vp' then
    select array_agg(x) into v_allowed from led_department_ids(p_project_id) as x;
    v_include_total := false;
  else
    return;
  end if;

  if p_department_id is not null then
    if not (p_department_id = any (coalesce(v_allowed, '{}'::uuid[]))) then
      return;
    end if;
    v_allowed := array[p_department_id];
  end if;

  select min_wellbeing_respondents, checkin_period_weeks * 7 into v_min, v_days from projects where id = p_project_id;

  return query
  with scores as (
    select * from _pulse_scores(p_project_id, 'member', 8)
  ),
  periods as (
    select generate_series(
      checkin_period_start(p_project_id, now()) - 7 * v_days,
      checkin_period_start(p_project_id, now()),
      make_interval(days => v_days)
    )::date as period_start
  ),
  groups as (
    select g.id as department_id from unnest(coalesce(v_allowed, '{}'::uuid[])) as g(id)
    union all
    select null::uuid where v_include_total
  ),
  counts as (
    select g.department_id, p.period_start,
           (select count(distinct s.user_id)
              from scores s
             where s.period_start = p.period_start
               and (g.department_id is null or s.department_id = g.department_id))::integer as n
    from groups g cross join periods p
  ),
  agg as (
    select g.department_id, s.period_start, s.question_id, avg(s.score) as avg_score
    from groups g
    join scores s on (g.department_id is null or s.department_id = g.department_id)
    group by 1, 2, 3
  )
  select c.department_id, c.period_start, a.question_id, round(a.avg_score, 2), c.n, false
  from   counts c
  join   agg a on a.department_id is not distinct from c.department_id and a.period_start = c.period_start
  where  c.n >= v_min
  union all
  select c.department_id, c.period_start, null::text, null::numeric, null::integer, true
  from   counts c
  where  c.n < v_min
  order  by 1 nulls first, 2, 3;
end;
$$;

create function get_exec_pulse(p_project_id uuid)
returns table (
  period_start     date,
  question_id      text,
  avg_score        numeric,
  respondent_count integer,
  suppressed       boolean
)
language plpgsql
security definer
stable
set search_path = public
as $$
#variable_conflict use_column
declare
  v_min  integer;
  v_days integer;
begin
  if not is_lc_president(p_project_id) then
    return;
  end if;

  select min_exec_respondents, checkin_period_weeks * 7 into v_min, v_days from projects where id = p_project_id;

  return query
  with scores as (
    select * from _pulse_scores(p_project_id, 'vp', 8)
  ),
  periods as (
    select generate_series(
      checkin_period_start(p_project_id, now()) - 7 * v_days,
      checkin_period_start(p_project_id, now()),
      make_interval(days => v_days)
    )::date as period_start
  ),
  counts as (
    select p.period_start,
           (select count(distinct s.user_id) from scores s where s.period_start = p.period_start)::integer as n
    from periods p
  ),
  agg as (
    select s.period_start, s.question_id, avg(s.score) as avg_score
    from scores s
    group by 1, 2
  )
  select c.period_start, a.question_id, round(a.avg_score, 2), c.n, false
  from   counts c
  join   agg a on a.period_start = c.period_start
  where  c.n >= v_min
  union all
  select c.period_start, null::text, null::numeric, null::integer, true
  from   counts c
  where  c.n < v_min
  order  by 1, 2;
end;
$$;

revoke execute on function get_member_pulse(uuid, uuid) from public, anon;
revoke execute on function get_exec_pulse(uuid)         from public, anon;
grant  execute on function get_member_pulse(uuid, uuid) to authenticated;
grant  execute on function get_exec_pulse(uuid)         to authenticated;

-- ── 4. Reminder follows the cadence ──────────────────────────────────────────

-- Friday 17:00 UTC of the last week of the period containing p_from, or of the
-- next period if that moment has passed.
create or replace function _next_checkin_due(p_project_id uuid, p_from timestamptz)
returns timestamptz
language sql
stable
security definer
set search_path = public
as $$
  with cfg as (select checkin_period_weeks * 7 as days from projects where id = p_project_id),
  due as (
    select checkin_period_start(p_project_id, p_from)::timestamptz
           + make_interval(days => cfg.days - 3, hours => 17) as at, cfg.days
    from cfg
  )
  select case when at > p_from then at else at + make_interval(days => days) end from due;
$$;

create or replace function _sync_checkin_reminder()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'DELETE' then
    delete from reminders where user_id = old.user_id and project_id = old.project_id and kind = 'weekly_checkin';
    return old;
  end if;
  if new.role in ('vp', 'member') then
    insert into reminders (user_id, project_id, scope, title, due_at, recurrence, kind, email_enabled, sent, completed)
    values (new.user_id, new.project_id, 'personal', 'Check-in', _next_checkin_due(new.project_id, now()),
            'weekly', 'weekly_checkin', false, false, false)
    on conflict (user_id, project_id) where kind = 'weekly_checkin' do nothing;
  else
    delete from reminders where user_id = new.user_id and project_id = new.project_id and kind = 'weekly_checkin';
  end if;
  return new;
end;
$$;

create or replace function _roll_checkin_reminder()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.kind = 'weekly_checkin' and new.completed and not old.completed then
    new.completed    := false;
    new.completed_at := null;
    new.due_at       := _next_checkin_due(new.project_id, greatest(coalesce(old.due_at, now()), now()) + interval '1 second');
  end if;
  return new;
end;
$$;

-- Submitting (or updating) a check-in moves the reminder to the next period.
create or replace function _checkin_recorded()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  -- Due date inside the period after the one just answered.
  v_next timestamptz := _next_checkin_due(
    new.project_id,
    (new.period_start + (select checkin_period_weeks * 7 from projects where id = new.project_id))::timestamptz);
begin
  update reminders
     set due_at = v_next
   where user_id = new.user_id and project_id = new.project_id and kind = 'weekly_checkin' and due_at < v_next;
  return new;
end;
$$;

drop trigger if exists trg_checkin_recorded on checkins;
create trigger trg_checkin_recorded
  after insert or update on checkins
  for each row execute function _checkin_recorded();

-- Journal entries no longer drive the reminder.
drop trigger if exists trg_checkin_submitted on journal_entries;
drop function if exists _checkin_submitted();
drop function if exists _next_checkin_due(timestamptz);

-- Retitle and re-time existing check-in reminders for the new cadence.
update reminders r
   set title = 'Check-in', due_at = _next_checkin_due(r.project_id, now())
 where r.kind = 'weekly_checkin' and not r.completed;

notify pgrst, 'reload schema';

-- ════════════════════════════════════════════════════════════════════════════
-- 20261017002_pipeline_goals.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 035: Exchange pipeline and term goals (KPIs).
--
--   departments.products   which AIESEC products a department runs
--                          (ogv, ogta, ogte, igv, igta, igte).
--   exchanges              one exchange participant (EP) moving through
--                          Signed up → Applied → Accepted → Approved →
--                          Realized → Finished. Holds personal data, so only
--                          the president, the department running the product
--                          (its VP and members) and the person who owns the
--                          exchange can see it.
--   goals                  term targets per department (or the whole LC).
--                          'pipeline' goals count exchanges that reached a
--                          stage in the goal's date range; 'manual' goals are
--                          updated by hand. Every LC member can see goals and
--                          their progress (via goal_progress(), which returns
--                          counts only); the president and the department's
--                          VP manage them.

-- ── 1. Products per department ───────────────────────────────────────────────

alter table departments add column if not exists products text[] not null default '{}';
alter table departments drop constraint if exists departments_products_check;
alter table departments add constraint departments_products_check
  check (products <@ array['ogv', 'ogta', 'ogte', 'igv', 'igta', 'igte']);

update departments set products = case name
    when 'Outgoing Global Volunteer'      then array['ogv']
    when 'Outgoing Global Talent/Teacher' then array['ogta', 'ogte']
    when 'Incoming Global Volunteer'      then array['igv']
    when 'Incoming Global Talent/Teacher' then array['igta', 'igte']
  end
where products = '{}'
  and name in ('Outgoing Global Volunteer', 'Outgoing Global Talent/Teacher',
               'Incoming Global Volunteer', 'Incoming Global Talent/Teacher');

create or replace function seed_default_departments(p_project_id uuid)
returns void
language sql
security definer
set search_path = public
as $$
  insert into departments (project_id, name, color, is_finance, sort_order, products)
  values
    (p_project_id, 'Outgoing Global Volunteer',       '#F85A40', false, 1, array['ogv']),
    (p_project_id, 'Outgoing Global Talent/Teacher',  '#0CB9C1', false, 2, array['ogta', 'ogte']),
    (p_project_id, 'Incoming Global Volunteer',       '#D9442B', false, 3, array['igv']),
    (p_project_id, 'Incoming Global Talent/Teacher',  '#0A8F96', false, 4, array['igta', 'igte']),
    (p_project_id, 'Marketing',                       '#FFC845', false, 5, '{}'),
    (p_project_id, 'Talent Management',               '#00C16E', false, 6, '{}'),
    (p_project_id, 'Finance & Legality',              '#037EF3', true,  7, '{}'),
    (p_project_id, 'Business Development',            '#7552CC', false, 8, '{}')
  on conflict (project_id, name) do nothing;
$$;
revoke execute on function seed_default_departments(uuid) from public, anon, authenticated;

-- ── 2. Exchanges ──────────────────────────────────────────────────────────────

create table if not exists exchanges (
  id            uuid primary key default gen_random_uuid(),
  project_id    uuid not null references projects(id) on delete cascade,
  product       text not null check (product in ('ogv', 'ogta', 'ogte', 'igv', 'igta', 'igte')),
  stage         text not null default 'signed_up'
                check (stage in ('signed_up', 'applied', 'accepted', 'approved', 'realized', 'finished')),
  person_name   text not null check (length(trim(person_name)) > 0),
  email         text,
  phone         text,
  opportunity   text,          -- project or position
  host_entity   text,          -- host LC / country (outgoing) or home LC / country (incoming)
  expa_id       text,
  expa_url      text check (expa_url is null or expa_url ~* '^https://'),
  department_id uuid references departments(id) on delete set null,
  owner_id      uuid references user_profiles(id) on delete set null,
  notes         text,
  signed_up_at  date not null default current_date,
  applied_at    date,
  accepted_at   date,
  approved_at   date,
  realized_at   date,
  finished_at   date,
  created_by    uuid references user_profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index if not exists exchanges_project_product_idx on exchanges (project_id, product, stage);

-- Fill in the department running the product, date every stage reached, and
-- keep owner / department inside the LC.
create or replace function _exchanges_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_rank integer := array_position(array['signed_up', 'applied', 'accepted', 'approved', 'realized', 'finished'], new.stage);
begin
  if new.department_id is null then
    select id into new.department_id from departments
    where project_id = new.project_id and new.product = any (products)
    order by sort_order limit 1;
  elsif not exists (select 1 from departments where id = new.department_id and project_id = new.project_id) then
    raise exception 'Department does not belong to this LC';
  end if;
  if new.owner_id is not null and not exists (
    select 1 from team_members where project_id = new.project_id and user_id = new.owner_id
  ) then
    raise exception 'The owner must be a member of this LC';
  end if;

  -- Reaching a stage implies the earlier ones; keep dates already recorded.
  if v_rank >= 2 then new.applied_at  := coalesce(new.applied_at,  current_date); end if;
  if v_rank >= 3 then new.accepted_at := coalesce(new.accepted_at, current_date); end if;
  if v_rank >= 4 then new.approved_at := coalesce(new.approved_at, current_date); end if;
  if v_rank >= 5 then new.realized_at := coalesce(new.realized_at, current_date); end if;
  if v_rank >= 6 then new.finished_at := coalesce(new.finished_at, current_date); end if;
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists trg_exchanges_guard on exchanges;
create trigger trg_exchanges_guard
  before insert or update on exchanges
  for each row execute function _exchanges_guard();

-- Who may see / work on an exchange.
create or replace function can_work_on_exchange(p_project_id uuid, p_department_id uuid, p_owner_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select is_lc_president(p_project_id)
      or p_owner_id = auth.uid()
      or exists (
           select 1 from team_members tm
           where tm.project_id = p_project_id and tm.user_id = auth.uid()
             and p_department_id is not null and tm.department_id = p_department_id
         )
      or p_department_id in (select led_department_ids(p_project_id));
$$;

alter table exchanges enable row level security;

drop policy if exists "department sees its exchanges" on exchanges;
create policy "department sees its exchanges" on exchanges
  for select using (can_work_on_exchange(project_id, department_id, owner_id));

drop policy if exists "department adds exchanges" on exchanges;
create policy "department adds exchanges" on exchanges
  for insert with check (
    auth_is_project_member(project_id)
    and created_by = auth.uid()
    and (
      is_lc_president(project_id)
      or exists (
        select 1 from departments d
        where d.project_id = exchanges.project_id and exchanges.product = any (d.products)
          and (d.vp_user_id = auth.uid()
               or d.id = (select tm.department_id from team_members tm where tm.project_id = exchanges.project_id and tm.user_id = auth.uid()))
      )
    )
  );

drop policy if exists "department updates exchanges" on exchanges;
create policy "department updates exchanges" on exchanges
  for update using (can_work_on_exchange(project_id, department_id, owner_id))
  with check (can_work_on_exchange(project_id, department_id, owner_id));

drop policy if exists "president or department VP deletes exchanges" on exchanges;
create policy "president or department VP deletes exchanges" on exchanges
  for delete using (is_lc_president(project_id) or department_id in (select led_department_ids(project_id)));

-- ── 3. Goals ──────────────────────────────────────────────────────────────────

create table if not exists goals (
  id            uuid primary key default gen_random_uuid(),
  project_id    uuid not null references projects(id) on delete cascade,
  department_id uuid references departments(id) on delete cascade,   -- null = whole LC
  title         text not null check (length(trim(title)) > 0),
  metric        text not null check (metric in ('manual', 'pipeline')),
  product       text check (product in ('ogv', 'ogta', 'ogte', 'igv', 'igta', 'igte')),
  stage         text check (stage in ('signed_up', 'applied', 'accepted', 'approved', 'realized', 'finished')),
  target        numeric not null check (target > 0),
  current_value numeric not null default 0 check (current_value >= 0),
  unit          text,
  starts_on     date not null,
  ends_on       date not null,
  created_by    uuid references user_profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  constraint goals_dates check (ends_on >= starts_on),
  constraint goals_pipeline_needs_stage check (metric = 'manual' or stage is not null)
);

create index if not exists goals_project_idx on goals (project_id, ends_on);

create or replace function _goals_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.department_id is not null and not exists (
    select 1 from departments where id = new.department_id and project_id = new.project_id
  ) then
    raise exception 'Department does not belong to this LC';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_goals_guard on goals;
create trigger trg_goals_guard
  before insert or update on goals
  for each row execute function _goals_guard();

alter table goals enable row level security;

drop policy if exists "lc members see goals" on goals;
create policy "lc members see goals" on goals
  for select using (auth_is_project_member(project_id));

drop policy if exists "president or department VP manages goals" on goals;
create policy "president or department VP manages goals" on goals
  for all using (
    is_lc_president(project_id) or (department_id is not null and department_id in (select led_department_ids(project_id)))
  ) with check (
    is_lc_president(project_id) or (department_id is not null and department_id in (select led_department_ids(project_id)))
  );

-- Progress for every goal in the LC: counts only, so members see KPI progress
-- without seeing the exchange participants behind it.
create or replace function goal_progress(p_project_id uuid)
returns table (goal_id uuid, current numeric)
language plpgsql
security definer
stable
set search_path = public
as $$
#variable_conflict use_column
begin
  if not auth_is_project_member(p_project_id) then
    return;
  end if;
  return query
  select g.id,
         case when g.metric = 'manual' then g.current_value
         else (
           select count(*)::numeric
           from   exchanges e
           where  e.project_id = g.project_id
             and  (g.product is not null and e.product = g.product
                   or g.product is null and (g.department_id is null or e.department_id = g.department_id))
             and  (case g.stage
                     when 'signed_up' then e.signed_up_at
                     when 'applied'   then e.applied_at
                     when 'accepted'  then e.accepted_at
                     when 'approved'  then e.approved_at
                     when 'realized'  then e.realized_at
                     when 'finished'  then e.finished_at
                   end) between g.starts_on and g.ends_on
         ) end
  from goals g
  where g.project_id = p_project_id;
end;
$$;

revoke execute on function goal_progress(uuid) from public, anon;
grant  execute on function goal_progress(uuid) to authenticated;

notify pgrst, 'reload schema';

-- ════════════════════════════════════════════════════════════════════════════
-- 20261017003_partners.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 036: Partner CRM (Business Development, iGT and anyone working with companies).
--
--   partners            company / organisation, stage, owner, next follow-up.
--   partner_contacts    people at the partner (names, emails, phones).
--   partner_activities  dated log of calls, emails, meetings and notes.
--
-- Visibility: the executive board (president and VPs) sees every partner;
-- other members see their own department's partners and the ones they own.
-- Contacts and activities follow their partner.

create table if not exists partners (
  id             uuid primary key default gen_random_uuid(),
  project_id     uuid not null references projects(id) on delete cascade,
  name           text not null check (length(trim(name)) > 0),
  industry       text,
  website        text check (website is null or website ~* '^https?://'),
  stage          text not null default 'lead'
                 check (stage in ('lead', 'contacted', 'meeting', 'proposal', 'negotiation', 'partner', 'lost')),
  department_id  uuid references departments(id) on delete set null,
  owner_id       uuid references user_profiles(id) on delete set null,
  next_follow_up date,
  notes          text,
  created_by     uuid references user_profiles(id) on delete set null,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create index if not exists partners_project_stage_idx on partners (project_id, stage);
create index if not exists partners_follow_up_idx on partners (project_id, owner_id, next_follow_up);

create table if not exists partner_contacts (
  id          uuid primary key default gen_random_uuid(),
  partner_id  uuid not null references partners(id) on delete cascade,
  name        text not null check (length(trim(name)) > 0),
  role_title  text,
  email       text,
  phone       text,
  notes       text,
  created_at  timestamptz not null default now()
);

create table if not exists partner_activities (
  id          uuid primary key default gen_random_uuid(),
  partner_id  uuid not null references partners(id) on delete cascade,
  kind        text not null default 'note' check (kind in ('note', 'call', 'email', 'meeting')),
  body        text not null check (length(trim(body)) > 0),
  happened_on date not null default current_date,
  author_id   uuid references user_profiles(id) on delete set null,
  created_at  timestamptz not null default now()
);

create index if not exists partner_activities_partner_idx on partner_activities (partner_id, happened_on desc);

create or replace function _partners_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.department_id is not null and not exists (
    select 1 from departments where id = new.department_id and project_id = new.project_id
  ) then
    raise exception 'Department does not belong to this LC';
  end if;
  if new.owner_id is not null and not exists (
    select 1 from team_members where project_id = new.project_id and user_id = new.owner_id
  ) then
    raise exception 'The owner must be a member of this LC';
  end if;
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists trg_partners_guard on partners;
create trigger trg_partners_guard
  before insert or update on partners
  for each row execute function _partners_guard();

-- The caller's own department in an LC (null if none).
create or replace function my_department_id(p_project_id uuid)
returns uuid
language sql
security definer
stable
set search_path = public
as $$
  select department_id from team_members where project_id = p_project_id and user_id = auth.uid();
$$;

-- Partner visibility from the row's own columns (usable while the row is being
-- inserted, unlike a lookup by id).
create or replace function partner_visible(p_project_id uuid, p_department_id uuid, p_owner_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select is_lc_exec(p_project_id)
      or p_owner_id = auth.uid()
      or (p_department_id is not null and p_department_id = my_department_id(p_project_id));
$$;

-- Can the caller see / work on an existing partner? (for contacts and activities)
create or replace function can_work_on_partner(p_partner_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from partners p
    where p.id = p_partner_id and partner_visible(p.project_id, p.department_id, p.owner_id)
  );
$$;

alter table partners           enable row level security;
alter table partner_contacts   enable row level security;
alter table partner_activities enable row level security;

drop policy if exists "partners visible to exec, department and owner" on partners;
create policy "partners visible to exec, department and owner" on partners
  for select using (partner_visible(project_id, department_id, owner_id));

drop policy if exists "members add partners for their department" on partners;
create policy "members add partners for their department" on partners
  for insert with check (
    created_by = auth.uid()
    and auth_is_project_member(project_id)
    and (
      is_lc_exec(project_id)
      or department_id = my_department_id(project_id)
    )
  );

drop policy if exists "people who can see a partner can update it" on partners;
create policy "people who can see a partner can update it" on partners
  for update using (partner_visible(project_id, department_id, owner_id)) with check (auth_is_project_member(project_id));

drop policy if exists "president, department VP or creator deletes partners" on partners;
create policy "president, department VP or creator deletes partners" on partners
  for delete using (
    is_lc_president(project_id)
    or created_by = auth.uid()
    or (department_id is not null and department_id in (select led_department_ids(project_id)))
  );

drop policy if exists "contacts follow their partner" on partner_contacts;
create policy "contacts follow their partner" on partner_contacts
  for all using (can_work_on_partner(partner_id)) with check (can_work_on_partner(partner_id));

drop policy if exists "activities follow their partner" on partner_activities;
create policy "activities follow their partner" on partner_activities
  for select using (can_work_on_partner(partner_id));

drop policy if exists "log activity on visible partners" on partner_activities;
create policy "log activity on visible partners" on partner_activities
  for insert with check (can_work_on_partner(partner_id) and author_id = auth.uid());

drop policy if exists "authors edit their own activity" on partner_activities;
create policy "authors edit their own activity" on partner_activities
  for delete using (author_id = auth.uid());

notify pgrst, 'reload schema';

-- ════════════════════════════════════════════════════════════════════════════
-- 20261017004_drive_handover.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 037: LC Drive (Bookmarks with folders and files) and term handover.
--
--   drive_folders     LC-wide folders, seeded per LC: Templates, Brand kit,
--                     Job descriptions, Important links, Handover. Every
--                     member sees them; the exec board manages them.
--   bookmarks         now "drive items": a link or an uploaded file, optionally
--                     in a folder. Personal items are visible only to their
--                     owner (previously any LC member could read them).
--   storage 'lc-drive' private bucket for uploaded files, opened through
--                     signed URLs; LC members read, the uploader or the exec
--                     board deletes.
--   handover_notes    one note per department per term (plus LC-wide notes from
--                     the president) for whoever takes over next. The exec board
--                     reads all; a department's members read theirs; the
--                     department's VP (or the president) writes.

-- ── 1. Folders ────────────────────────────────────────────────────────────────

create table if not exists drive_folders (
  id          uuid primary key default gen_random_uuid(),
  project_id  uuid not null references projects(id) on delete cascade,
  name        text not null check (length(trim(name)) > 0),
  sort_order  integer not null default 0,
  created_by  uuid references user_profiles(id) on delete set null,
  created_at  timestamptz not null default now(),
  unique (project_id, name)
);

create or replace function seed_default_drive_folders(p_project_id uuid)
returns void
language sql
security definer
set search_path = public
as $$
  insert into drive_folders (project_id, name, sort_order)
  select p_project_id, f.name, f.ord
  from unnest(array['Templates', 'Brand kit', 'Job descriptions', 'Important links', 'Handover'])
       with ordinality as f(name, ord)
  on conflict (project_id, name) do nothing;
$$;
revoke execute on function seed_default_drive_folders(uuid) from public, anon, authenticated;

create or replace function _seed_lc_drive_folders()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform seed_default_drive_folders(new.id);
  return new;
end;
$$;

drop trigger if exists trg_seed_lc_drive_folders on projects;
create trigger trg_seed_lc_drive_folders
  after insert on projects
  for each row execute function _seed_lc_drive_folders();

select seed_default_drive_folders(p.id)
from projects p
where not exists (select 1 from drive_folders f where f.project_id = p.id);

alter table drive_folders enable row level security;

drop policy if exists "lc members see folders" on drive_folders;
create policy "lc members see folders" on drive_folders
  for select using (auth_is_project_member(project_id));

drop policy if exists "exec manages folders" on drive_folders;
create policy "exec manages folders" on drive_folders
  for all using (is_lc_exec(project_id)) with check (is_lc_exec(project_id));

-- ── 2. Drive items (bookmarks) ───────────────────────────────────────────────

alter table bookmarks
  add column if not exists folder_id    uuid references drive_folders(id) on delete set null,
  add column if not exists kind         text not null default 'link',
  add column if not exists storage_path text,
  add column if not exists file_name    text,
  add column if not exists mime_type    text,
  add column if not exists size_bytes   bigint;

alter table bookmarks drop constraint if exists bookmarks_kind_check;
alter table bookmarks add constraint bookmarks_kind_check check (
  (kind = 'link' and storage_path is null)
  or (kind = 'file' and storage_path is not null)
);

create or replace function _bookmarks_folder_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.folder_id is not null and not exists (
    select 1 from drive_folders where id = new.folder_id and project_id = new.project_id
  ) then
    raise exception 'Folder does not belong to this LC';
  end if;
  if new.kind = 'file' and split_part(new.storage_path, '/', 1) <> new.project_id::text then
    raise exception 'File is not stored under this LC';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_bookmarks_folder_guard on bookmarks;
create trigger trg_bookmarks_folder_guard
  before insert or update on bookmarks
  for each row execute function _bookmarks_folder_guard();

-- Personal items were readable by every LC member; keep them private.
drop policy if exists "project members can read bookmarks" on bookmarks;
create policy "project members can read bookmarks" on bookmarks
  for select using (
    (coalesce(scope, 'lab') <> 'personal' and auth_is_project_member(project_id))
    or (scope = 'personal' and added_by = auth.uid())
    or (
      scope = 'project'
      and sub_project_id is not null
      and exists (
        select 1 from sub_project_members spm
        where spm.sub_project_id = bookmarks.sub_project_id and spm.user_id = auth.uid()
      )
    )
  );

drop policy if exists "members can update shared bookmarks" on bookmarks;
create policy "members can update shared bookmarks" on bookmarks
  for update using (
    (scope = 'personal' and added_by = auth.uid())
    or (coalesce(scope, 'lab') <> 'personal' and auth_is_project_member(project_id))
  ) with check (auth_is_project_member(project_id) or added_by = auth.uid());

-- ── 3. Files bucket ──────────────────────────────────────────────────────────

insert into storage.buckets (id, name, public, file_size_limit)
values ('lc-drive', 'lc-drive', false, 26214400)
on conflict (id) do update set public = false;

drop policy if exists "lc-drive: members upload to their LC" on storage.objects;
create policy "lc-drive: members upload to their LC" on storage.objects
  for insert to authenticated with check (
    bucket_id = 'lc-drive' and auth_is_project_member(_try_uuid((storage.foldername(name))[1]))
  );

drop policy if exists "lc-drive: members read their LC" on storage.objects;
create policy "lc-drive: members read their LC" on storage.objects
  for select to authenticated using (
    bucket_id = 'lc-drive'
    and auth_is_project_member(_try_uuid((storage.foldername(name))[1]))
    -- personal files stay with their owner
    and not exists (
      select 1 from bookmarks b
      where b.storage_path = storage.objects.name and b.scope = 'personal' and b.added_by <> auth.uid()
    )
  );

drop policy if exists "lc-drive: uploader or exec deletes" on storage.objects;
create policy "lc-drive: uploader or exec deletes" on storage.objects
  for delete to authenticated using (
    bucket_id = 'lc-drive'
    and (owner = auth.uid() or is_lc_exec(_try_uuid((storage.foldername(name))[1])))
  );

-- ── 4. Handover notes ────────────────────────────────────────────────────────

create table if not exists handover_notes (
  id            uuid primary key default gen_random_uuid(),
  project_id    uuid not null references projects(id) on delete cascade,
  department_id uuid references departments(id) on delete cascade,   -- null = LC-wide (president)
  term_label    text not null check (length(trim(term_label)) > 0),  -- e.g. "2026/27"
  title         text not null check (length(trim(title)) > 0),
  body          text not null default '',
  updated_by    uuid references user_profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique nulls not distinct (project_id, department_id, term_label)
);

create or replace function _handover_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.department_id is not null and not exists (
    select 1 from departments where id = new.department_id and project_id = new.project_id
  ) then
    raise exception 'Department does not belong to this LC';
  end if;
  new.updated_at := now();
  new.updated_by := coalesce(auth.uid(), new.updated_by);
  return new;
end;
$$;

drop trigger if exists trg_handover_guard on handover_notes;
create trigger trg_handover_guard
  before insert or update on handover_notes
  for each row execute function _handover_guard();

alter table handover_notes enable row level security;

drop policy if exists "handover readable by exec and the department" on handover_notes;
create policy "handover readable by exec and the department" on handover_notes
  for select using (
    is_lc_exec(project_id)
    or (department_id is not null and department_id = my_department_id(project_id))
  );

drop policy if exists "handover written by the department VP or president" on handover_notes;
create policy "handover written by the department VP or president" on handover_notes
  for all using (
    is_lc_president(project_id) or (department_id is not null and department_id in (select led_department_ids(project_id)))
  ) with check (
    is_lc_president(project_id) or (department_id is not null and department_id in (select led_department_ids(project_id)))
  );

notify pgrst, 'reload schema';

-- ════════════════════════════════════════════════════════════════════════════
-- 20261018001_departments_by_president.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 038: New LCs start without departments; the president creates them.
--
-- Until now every new LC was given the eight AIESEC departments automatically.
-- LCs organise their committees differently (oGX, oGT, oGV, …), so the
-- president now creates them in Settings → Departments, where the usual AIESEC
-- departments are offered as one-click suggestions. Existing LCs keep the
-- departments they already have.
--
-- seed_default_departments() stays (not callable through the API) for scripts
-- that want the classic setup.

drop trigger if exists trg_seed_lc_departments on projects;
drop function if exists _seed_lc_departments();

notify pgrst, 'reload schema';

-- ════════════════════════════════════════════════════════════════════════════
-- 20261018002_pipeline_completed_import.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 039: Exchange pipeline — "Completed" stage and EXPA CSV import.
--
--   * Stages are now Signed up → Applied → Accepted → Approved → Realized →
--     Finished → Completed (exchanges.completed_at, goals can target it).
--   * Stage dates: when an exchange arrives at a stage with earlier dates
--     missing (typical for imports), each missing date takes the next known
--     later date instead of today, so conversion and "this term" numbers stay
--     right. Sign-up is never after the application.
--   * expa_id is unique per LC, so re-importing an EXPA export updates the
--     exchanges already there instead of duplicating them.
--   * import_exchanges(lc, product, rows) inserts or updates many exchanges in
--     one call. It runs with the caller's own rights (SECURITY INVOKER), so the
--     usual RLS decides what each person may add or change; rows it can't
--     write are counted and reported back, not silently dropped.

-- ── 1. Completed stage ───────────────────────────────────────────────────────

alter table exchanges add column if not exists completed_at date;

alter table exchanges drop constraint if exists exchanges_stage_check;
alter table exchanges add constraint exchanges_stage_check
  check (stage in ('signed_up', 'applied', 'accepted', 'approved', 'realized', 'finished', 'completed'));

alter table goals drop constraint if exists goals_stage_check;
alter table goals add constraint goals_stage_check
  check (stage in ('signed_up', 'applied', 'accepted', 'approved', 'realized', 'finished', 'completed'));

create or replace function _exchanges_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_rank integer := array_position(
    array['signed_up', 'applied', 'accepted', 'approved', 'realized', 'finished', 'completed'], new.stage);
begin
  if new.department_id is null then
    select id into new.department_id from departments
    where project_id = new.project_id and new.product = any (products)
    order by sort_order limit 1;
  elsif not exists (select 1 from departments where id = new.department_id and project_id = new.project_id) then
    raise exception 'Department does not belong to this LC';
  end if;
  if new.owner_id is not null and not exists (
    select 1 from team_members where project_id = new.project_id and user_id = new.owner_id
  ) then
    raise exception 'The owner must be a member of this LC';
  end if;

  -- Reaching a stage implies the earlier ones. A missing date takes the next
  -- known later date (imports often carry only the latest), else today.
  if v_rank >= 7 then new.completed_at := coalesce(new.completed_at, current_date); end if;
  if v_rank >= 6 then new.finished_at  := coalesce(new.finished_at,  new.completed_at, current_date); end if;
  if v_rank >= 5 then new.realized_at  := coalesce(new.realized_at,  new.finished_at,  current_date); end if;
  if v_rank >= 4 then new.approved_at  := coalesce(new.approved_at,  new.realized_at,  current_date); end if;
  if v_rank >= 3 then new.accepted_at  := coalesce(new.accepted_at,  new.approved_at,  current_date); end if;
  if v_rank >= 2 then new.applied_at   := coalesce(new.applied_at,   new.accepted_at,  current_date); end if;
  new.signed_up_at := least(coalesce(new.signed_up_at, current_date), coalesce(new.applied_at, current_date));
  new.updated_at := now();
  return new;
end;
$$;

create or replace function goal_progress(p_project_id uuid)
returns table (goal_id uuid, current numeric)
language plpgsql
security definer
stable
set search_path = public
as $$
#variable_conflict use_column
begin
  if not auth_is_project_member(p_project_id) then
    return;
  end if;
  return query
  select g.id,
         case when g.metric = 'manual' then g.current_value
         else (
           select count(*)::numeric
           from   exchanges e
           where  e.project_id = g.project_id
             and  (g.product is not null and e.product = g.product
                   or g.product is null and (g.department_id is null or e.department_id = g.department_id))
             and  (case g.stage
                     when 'signed_up' then e.signed_up_at
                     when 'applied'   then e.applied_at
                     when 'accepted'  then e.accepted_at
                     when 'approved'  then e.approved_at
                     when 'realized'  then e.realized_at
                     when 'finished'  then e.finished_at
                     when 'completed' then e.completed_at
                   end) between g.starts_on and g.ends_on
         ) end
  from goals g
  where g.project_id = p_project_id;
end;
$$;

-- ── 2. One exchange per EXPA application per LC ──────────────────────────────

create unique index if not exists exchanges_project_expa_id_key
  on exchanges (project_id, expa_id) where expa_id is not null;

-- ── 3. Bulk import ───────────────────────────────────────────────────────────
-- p_rows: [{ expa_id, person_name, email, phone, opportunity, host_entity,
--            expa_url, stage, signed_up_at, applied_at, accepted_at,
--            approved_at, realized_at, finished_at, completed_at }, …]

create or replace function import_exchanges(p_project_id uuid, p_product text, p_rows jsonb)
returns table (inserted integer, updated integer, failed integer, errors text[])
language plpgsql
security invoker
set search_path = public
as $$
declare
  r        jsonb;
  v_id     uuid;
  v_expa   text;
  v_name   text;
  v_ins    integer := 0;
  v_upd    integer := 0;
  v_fail   integer := 0;
  v_errors text[]  := '{}';
begin
  if jsonb_typeof(p_rows) <> 'array' then
    raise exception 'Expected a list of rows';
  end if;
  if jsonb_array_length(p_rows) > 2000 then
    raise exception 'Import at most 2000 rows at a time';
  end if;

  for r in select * from jsonb_array_elements(p_rows) loop
    v_expa := nullif(trim(r->>'expa_id'), '');
    v_name := coalesce(nullif(trim(r->>'person_name'), ''), v_expa, '(no name)');
    begin
      v_id := null;
      if v_expa is not null then
        select id into v_id from exchanges where project_id = p_project_id and expa_id = v_expa;
      end if;

      if v_id is not null then
        update exchanges set
          stage        = coalesce(nullif(r->>'stage', ''), stage),
          person_name  = coalesce(nullif(trim(r->>'person_name'), ''), person_name),
          email        = coalesce(nullif(trim(r->>'email'), ''), email),
          phone        = coalesce(nullif(trim(r->>'phone'), ''), phone),
          opportunity  = coalesce(nullif(trim(r->>'opportunity'), ''), opportunity),
          host_entity  = coalesce(nullif(trim(r->>'host_entity'), ''), host_entity),
          expa_url     = coalesce(nullif(trim(r->>'expa_url'), ''), expa_url),
          signed_up_at = coalesce((r->>'signed_up_at')::date, signed_up_at),
          applied_at   = coalesce((r->>'applied_at')::date, applied_at),
          accepted_at  = coalesce((r->>'accepted_at')::date, accepted_at),
          approved_at  = coalesce((r->>'approved_at')::date, approved_at),
          realized_at  = coalesce((r->>'realized_at')::date, realized_at),
          finished_at  = coalesce((r->>'finished_at')::date, finished_at),
          completed_at = coalesce((r->>'completed_at')::date, completed_at)
        where id = v_id;
        if not found then
          raise exception 'you can''t edit this exchange';
        end if;
        v_upd := v_upd + 1;
      else
        insert into exchanges (project_id, product, stage, person_name, email, phone, opportunity, host_entity,
                               expa_id, expa_url, signed_up_at, applied_at, accepted_at, approved_at,
                               realized_at, finished_at, completed_at, created_by)
        values (p_project_id, p_product, coalesce(nullif(r->>'stage', ''), 'signed_up'), v_name,
                nullif(trim(r->>'email'), ''), nullif(trim(r->>'phone'), ''),
                nullif(trim(r->>'opportunity'), ''), nullif(trim(r->>'host_entity'), ''),
                v_expa, nullif(trim(r->>'expa_url'), ''),
                coalesce((r->>'signed_up_at')::date, (r->>'applied_at')::date, current_date),
                (r->>'applied_at')::date, (r->>'accepted_at')::date, (r->>'approved_at')::date,
                (r->>'realized_at')::date, (r->>'finished_at')::date, (r->>'completed_at')::date,
                auth.uid());
        v_ins := v_ins + 1;
      end if;
    exception when others then
      v_fail := v_fail + 1;
      if coalesce(array_length(v_errors, 1), 0) < 20 then
        v_errors := v_errors || (v_name || ': ' ||
          case when sqlstate = '23505' then 'already in the pipeline, in a department you can''t see'
               when sqlstate = '42501' then 'you can''t add exchanges for this product'
               else sqlerrm end);
      end if;
    end;
  end loop;

  return query select v_ins, v_upd, v_fail, v_errors;
end;
$$;

revoke execute on function import_exchanges(uuid, text, jsonb) from public, anon;
grant  execute on function import_exchanges(uuid, text, jsonb) to authenticated;

notify pgrst, 'reload schema';

-- ════════════════════════════════════════════════════════════════════════════
-- 20261019001_member_lifecycle.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 040: Member lifecycle (Talent Management).
--
--   recruits             recruitment intake: people who applied to join the LC,
--                        moving Applied → Interview → Offer → Joined (or
--                        Rejected / Withdrawn). Personal data: the exec board
--                        only.
--   onboarding_steps     the LC's onboarding checklist (seeded with five steps,
--                        edited by the exec board; a step can be limited to one
--                        department).
--   member_onboarding    which steps each member has done. Members tick their
--                        own; the president and the member's VP can tick too.
--   team_members         term_start / term_end per member, set with
--                        set_member_term() by the president or the member's VP.
--   user_profiles        last_seen_at, refreshed by touch_last_seen() when the
--                        app opens.
--   member_activity()    inactivity signals per member for the president (all)
--                        and VPs (their departments): last seen, events attended
--                        vs held, tabling no-shows, overdue tasks. Deliberately
--                        NOT check-in participation: the check-in promises that
--                        nobody can see who answered.

-- ── 1. Recruitment intake ────────────────────────────────────────────────────

create table if not exists recruits (
  id             uuid primary key default gen_random_uuid(),
  project_id     uuid not null references projects(id) on delete cascade,
  name           text not null check (length(trim(name)) > 0),
  email          text,
  phone          text,
  source         text,                 -- tabling, info session, social media, referral, form…
  department_id  uuid references departments(id) on delete set null,   -- department they're interested in
  stage          text not null default 'applied'
                 check (stage in ('applied', 'interview', 'offer', 'joined', 'rejected', 'withdrawn')),
  interview_at   timestamptz,
  notes          text,
  owner_id       uuid references user_profiles(id) on delete set null,
  applied_on     date not null default current_date,
  created_by     uuid references user_profiles(id) on delete set null,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create index if not exists recruits_project_stage_idx on recruits (project_id, stage);
create unique index if not exists recruits_project_email_key on recruits (project_id, lower(email)) where email is not null;

create or replace function _recruits_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.department_id is not null and not exists (
    select 1 from departments where id = new.department_id and project_id = new.project_id
  ) then
    raise exception 'Department does not belong to this LC';
  end if;
  if new.owner_id is not null and not exists (
    select 1 from team_members where project_id = new.project_id and user_id = new.owner_id
  ) then
    raise exception 'The owner must be a member of this LC';
  end if;
  new.email := nullif(lower(trim(new.email)), '');
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists trg_recruits_guard on recruits;
create trigger trg_recruits_guard
  before insert or update on recruits
  for each row execute function _recruits_guard();

alter table recruits enable row level security;

drop policy if exists "exec manages recruits" on recruits;
create policy "exec manages recruits" on recruits
  for all using (is_lc_exec(project_id)) with check (is_lc_exec(project_id));

-- ── 2. Onboarding checklist ──────────────────────────────────────────────────

create table if not exists onboarding_steps (
  id            uuid primary key default gen_random_uuid(),
  project_id    uuid not null references projects(id) on delete cascade,
  title         text not null check (length(trim(title)) > 0),
  description   text,
  department_id uuid references departments(id) on delete cascade,   -- null = every new member
  sort_order    integer not null default 0,
  created_at    timestamptz not null default now()
);

create table if not exists member_onboarding (
  project_id uuid not null references projects(id) on delete cascade,
  user_id    uuid not null references user_profiles(id) on delete cascade,
  step_id    uuid not null references onboarding_steps(id) on delete cascade,
  done_at    timestamptz not null default now(),
  done_by    uuid references user_profiles(id) on delete set null,
  primary key (user_id, step_id)
);

create or replace function seed_default_onboarding_steps(p_project_id uuid)
returns void
language sql
security definer
set search_path = public
as $$
  insert into onboarding_steps (project_id, title, description, sort_order)
  select p_project_id, s.title, s.descr, s.ord
  from (values
    ('Meet your VP',                    'A first 1:1 with the VP of your department.', 1),
    ('Join the LC chat',                'Say hi in the LC channel in Chat.', 2),
    ('Read the LC handbook',            'It is in the LC Drive, in Handover or Templates.', 3),
    ('Attend your first LC meeting',    null, 4),
    ('Do your first check-in',          'About a minute, every two weeks. Only averages are shared.', 5)
  ) as s(title, descr, ord)
  where not exists (select 1 from onboarding_steps where project_id = p_project_id);
$$;
revoke execute on function seed_default_onboarding_steps(uuid) from public, anon, authenticated;

create or replace function _seed_lc_onboarding()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform seed_default_onboarding_steps(new.id);
  return new;
end;
$$;

drop trigger if exists trg_seed_lc_onboarding on projects;
create trigger trg_seed_lc_onboarding
  after insert on projects
  for each row execute function _seed_lc_onboarding();

select seed_default_onboarding_steps(p.id) from projects p;

create or replace function _member_onboarding_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  select project_id into new.project_id from onboarding_steps where id = new.step_id;
  if not exists (select 1 from team_members where project_id = new.project_id and user_id = new.user_id) then
    raise exception 'Onboarding is for members of this LC';
  end if;
  new.done_by := coalesce(auth.uid(), new.done_by);
  return new;
end;
$$;

drop trigger if exists trg_member_onboarding_guard on member_onboarding;
create trigger trg_member_onboarding_guard
  before insert on member_onboarding
  for each row execute function _member_onboarding_guard();

alter table onboarding_steps  enable row level security;
alter table member_onboarding enable row level security;

drop policy if exists "lc members see onboarding steps" on onboarding_steps;
create policy "lc members see onboarding steps" on onboarding_steps
  for select using (auth_is_project_member(project_id));

drop policy if exists "exec manages onboarding steps" on onboarding_steps;
create policy "exec manages onboarding steps" on onboarding_steps
  for all using (is_lc_exec(project_id)) with check (is_lc_exec(project_id));

-- Who may see / tick a member's onboarding: the member, the president, their VP.
create or replace function can_manage_member(p_project_id uuid, p_user_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select p_user_id = auth.uid()
      or is_lc_president(p_project_id)
      or (lc_role(p_project_id) = 'vp' and in_led_department(p_project_id, p_user_id));
$$;

drop policy if exists "member, VP or president sees onboarding" on member_onboarding;
create policy "member, VP or president sees onboarding" on member_onboarding
  for select using (can_manage_member(project_id, user_id));

drop policy if exists "member, VP or president ticks onboarding" on member_onboarding;
create policy "member, VP or president ticks onboarding" on member_onboarding
  for insert with check (
    can_manage_member((select s.project_id from onboarding_steps s where s.id = step_id), user_id)
  );

drop policy if exists "member, VP or president unticks onboarding" on member_onboarding;
create policy "member, VP or president unticks onboarding" on member_onboarding
  for delete using (can_manage_member(project_id, user_id));

-- ── 3. Term dates ────────────────────────────────────────────────────────────

alter table team_members
  add column if not exists term_start date,
  add column if not exists term_end   date;

alter table team_members drop constraint if exists team_members_term_dates;
alter table team_members add constraint team_members_term_dates
  check (term_end is null or term_start is null or term_end >= term_start);

create or replace function set_member_term(p_project_id uuid, p_user_id uuid, p_start date, p_end date)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not (is_lc_president(p_project_id) or (lc_role(p_project_id) = 'vp' and in_led_department(p_project_id, p_user_id))) then
    raise exception 'Only the president or the member''s VP can set term dates';
  end if;
  update team_members set term_start = p_start, term_end = p_end
   where project_id = p_project_id and user_id = p_user_id;
  if not found then
    raise exception 'Member not found';
  end if;
end;
$$;

revoke execute on function set_member_term(uuid, uuid, date, date) from public, anon;
grant  execute on function set_member_term(uuid, uuid, date, date) to authenticated;

-- ── 4. Last seen ─────────────────────────────────────────────────────────────

alter table user_profiles add column if not exists last_seen_at timestamptz;

create or replace function touch_last_seen()
returns void
language sql
security definer
set search_path = public
as $$
  update user_profiles set last_seen_at = now()
   where id = auth.uid() and (last_seen_at is null or last_seen_at < now() - interval '1 hour');
$$;

revoke execute on function touch_last_seen() from public, anon;
grant  execute on function touch_last_seen() to authenticated;

-- ── 5. Activity signals ──────────────────────────────────────────────────────

create or replace function member_activity(p_project_id uuid, p_days integer default 60)
returns table (
  user_id          uuid,
  department_id    uuid,
  role             text,
  term_start       date,
  term_end         date,
  last_seen_at     timestamptz,
  events_held      integer,   -- LC-wide or their department's events in the window, already started
  events_attended  integer,
  tabling_no_shows integer,
  overdue_tasks    integer,
  onboarding_done  integer,
  onboarding_total integer
)
language plpgsql
security definer
stable
set search_path = public
as $$
#variable_conflict use_column
declare
  v_role text := lc_role(p_project_id);
  v_from date := current_date - p_days;
begin
  if v_role not in ('president', 'vp') then
    return;
  end if;
  return query
  select tm.user_id, tm.department_id, tm.role, tm.term_start, tm.term_end, up.last_seen_at,
         (select count(*)::int from lc_events e
           where e.project_id = p_project_id and e.starts_on between v_from and current_date
             and (e.department_id is null or e.department_id = tm.department_id)),
         (select count(*)::int from event_attendance a join lc_events e on e.id = a.event_id
           where a.project_id = p_project_id and a.user_id = tm.user_id and e.starts_on between v_from and current_date),
         (select count(*)::int from tabling_signups su join tabling_slots s on s.id = su.slot_id
           where su.project_id = p_project_id and su.user_id = tm.user_id and su.status = 'no_show'
             and s.starts_at::date >= v_from),
         (select count(*)::int from tasks t join task_assignees ta on ta.task_id = t.id
           where t.project_id = p_project_id and ta.user_id = tm.user_id and t.status <> 'done'
             and not coalesce(t.archived, false) and t.due_date < current_date),
         (select count(*)::int from member_onboarding mo where mo.project_id = p_project_id and mo.user_id = tm.user_id),
         (select count(*)::int from onboarding_steps os
           where os.project_id = p_project_id and (os.department_id is null or os.department_id = tm.department_id))
  from team_members tm
  join user_profiles up on up.id = tm.user_id
  where tm.project_id = p_project_id
    and (v_role = 'president' or in_led_department(p_project_id, tm.user_id));
end;
$$;

revoke execute on function member_activity(uuid, integer) from public, anon;
grant  execute on function member_activity(uuid, integer) to authenticated;

notify pgrst, 'reload schema';

-- ════════════════════════════════════════════════════════════════════════════
-- 20261019002_tracker_import.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 041: Import trackers (Google Sheets / CSV) into partners, recruits and tasks.
--
-- Same contract as import_exchanges(): SECURITY INVOKER (the caller's RLS
-- decides what they may write), one sub-transaction per row, and a summary of
-- inserted / updated / failed rows with up to 20 reasons. Re-importing the same
-- sheet updates instead of duplicating:
--   partners  matched by name (case-insensitive)
--   recruits  matched by email
--   tasks     a task with the same title and due date is left alone

-- ── Partners ──────────────────────────────────────────────────────────────────
-- rows: [{ name, industry, website, stage, department_id, next_follow_up, notes,
--          contact_name, contact_role, contact_email, contact_phone }]

create or replace function import_partners(p_project_id uuid, p_rows jsonb)
returns table (inserted integer, updated integer, failed integer, errors text[])
language plpgsql
security invoker
set search_path = public
as $$
declare
  r jsonb; v_id uuid; v_name text;
  v_ins integer := 0; v_upd integer := 0; v_fail integer := 0; v_errors text[] := '{}';
begin
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 2000 then
    raise exception 'Expected a list of at most 2000 rows';
  end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    v_name := nullif(trim(r->>'name'), '');
    begin
      if v_name is null then raise exception 'no organisation name'; end if;
      select id into v_id from partners where project_id = p_project_id and lower(name) = lower(v_name) limit 1;
      if v_id is not null then
        update partners set
          industry       = coalesce(nullif(trim(r->>'industry'), ''), industry),
          website        = coalesce(nullif(trim(r->>'website'), ''), website),
          stage          = coalesce(nullif(r->>'stage', ''), stage),
          next_follow_up = coalesce((r->>'next_follow_up')::date, next_follow_up),
          notes          = coalesce(nullif(trim(r->>'notes'), ''), notes)
        where id = v_id;
        if not found then raise exception 'you can''t edit this partner'; end if;
        v_upd := v_upd + 1;
      else
        insert into partners (project_id, name, industry, website, stage, department_id, next_follow_up, notes, created_by)
        values (p_project_id, v_name, nullif(trim(r->>'industry'), ''), nullif(trim(r->>'website'), ''),
                coalesce(nullif(r->>'stage', ''), 'lead'), (r->>'department_id')::uuid,
                (r->>'next_follow_up')::date, nullif(trim(r->>'notes'), ''), auth.uid())
        returning id into v_id;
        v_ins := v_ins + 1;
      end if;
      if nullif(trim(r->>'contact_name'), '') is not null and not exists (
        select 1 from partner_contacts where partner_id = v_id and lower(name) = lower(trim(r->>'contact_name'))
      ) then
        insert into partner_contacts (partner_id, name, role_title, email, phone)
        values (v_id, trim(r->>'contact_name'), nullif(trim(r->>'contact_role'), ''),
                nullif(trim(r->>'contact_email'), ''), nullif(trim(r->>'contact_phone'), ''));
      end if;
    exception when others then
      v_fail := v_fail + 1;
      if coalesce(array_length(v_errors, 1), 0) < 20 then
        v_errors := v_errors || (coalesce(v_name, '(no name)') || ': ' ||
          case when sqlstate = '42501' then 'you can''t add partners for that department' else sqlerrm end);
      end if;
    end;
  end loop;
  return query select v_ins, v_upd, v_fail, v_errors;
end;
$$;

-- ── Recruits ──────────────────────────────────────────────────────────────────
-- rows: [{ name, email, phone, source, department_id, stage, applied_on, notes }]

create or replace function import_recruits(p_project_id uuid, p_rows jsonb)
returns table (inserted integer, updated integer, failed integer, errors text[])
language plpgsql
security invoker
set search_path = public
as $$
declare
  r jsonb; v_id uuid; v_name text; v_email text;
  v_ins integer := 0; v_upd integer := 0; v_fail integer := 0; v_errors text[] := '{}';
begin
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 2000 then
    raise exception 'Expected a list of at most 2000 rows';
  end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    v_name := nullif(trim(r->>'name'), '');
    v_email := nullif(lower(trim(r->>'email')), '');
    begin
      if v_name is null then raise exception 'no name'; end if;
      v_id := null;
      if v_email is not null then
        select id into v_id from recruits where project_id = p_project_id and email = v_email;
      end if;
      if v_id is not null then
        update recruits set
          name          = v_name,
          phone         = coalesce(nullif(trim(r->>'phone'), ''), phone),
          source        = coalesce(nullif(trim(r->>'source'), ''), source),
          department_id = coalesce((r->>'department_id')::uuid, department_id),
          stage         = coalesce(nullif(r->>'stage', ''), stage),
          notes         = coalesce(nullif(trim(r->>'notes'), ''), notes)
        where id = v_id;
        if not found then raise exception 'you can''t edit recruits'; end if;
        v_upd := v_upd + 1;
      else
        insert into recruits (project_id, name, email, phone, source, department_id, stage, applied_on, notes, created_by)
        values (p_project_id, v_name, v_email, nullif(trim(r->>'phone'), ''), nullif(trim(r->>'source'), ''),
                (r->>'department_id')::uuid, coalesce(nullif(r->>'stage', ''), 'applied'),
                coalesce((r->>'applied_on')::date, current_date), nullif(trim(r->>'notes'), ''), auth.uid());
        v_ins := v_ins + 1;
      end if;
    exception when others then
      v_fail := v_fail + 1;
      if coalesce(array_length(v_errors, 1), 0) < 20 then
        v_errors := v_errors || (coalesce(v_name, '(no name)') || ': ' ||
          case when sqlstate = '42501' then 'only the exec board can add recruits' else sqlerrm end);
      end if;
    end;
  end loop;
  return query select v_ins, v_upd, v_fail, v_errors;
end;
$$;

-- ── Tasks ─────────────────────────────────────────────────────────────────────
-- rows: [{ title, description, status, priority, due_date, department_id, assignee_ids: [uuid] }]

create or replace function import_tasks(p_project_id uuid, p_rows jsonb)
returns table (inserted integer, updated integer, failed integer, errors text[])
language plpgsql
security invoker
set search_path = public
as $$
declare
  r jsonb; v_id uuid; v_title text; v_due date; a text;
  v_ins integer := 0; v_skip integer := 0; v_fail integer := 0; v_errors text[] := '{}';
begin
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 2000 then
    raise exception 'Expected a list of at most 2000 rows';
  end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    v_title := nullif(trim(r->>'title'), '');
    begin
      if v_title is null then raise exception 'no title'; end if;
      v_due := (r->>'due_date')::date;
      if exists (select 1 from tasks where project_id = p_project_id and title = v_title and due_date is not distinct from v_due) then
        v_skip := v_skip + 1;
        continue;
      end if;
      insert into tasks (project_id, title, description, status, priority, due_date, department_id, scope, created_by)
      values (p_project_id, v_title, coalesce(r->>'description', ''), coalesce(nullif(r->>'status', ''), 'todo'),
              coalesce(nullif(r->>'priority', ''), 'medium'), v_due, (r->>'department_id')::uuid, 'lab', auth.uid())
      returning id into v_id;
      for a in select * from jsonb_array_elements_text(coalesce(r->'assignee_ids', '[]'::jsonb)) loop
        insert into task_assignees (task_id, user_id) values (v_id, a::uuid) on conflict do nothing;
      end loop;
      v_ins := v_ins + 1;
    exception when others then
      v_fail := v_fail + 1;
      if coalesce(array_length(v_errors, 1), 0) < 20 then
        v_errors := v_errors || (coalesce(v_title, '(no title)') || ': ' || sqlerrm);
      end if;
    end;
  end loop;
  -- "updated" reports tasks that were already there and left alone.
  return query select v_ins, v_skip, v_fail, v_errors;
end;
$$;

revoke execute on function import_partners(uuid, jsonb) from public, anon;
revoke execute on function import_recruits(uuid, jsonb) from public, anon;
revoke execute on function import_tasks(uuid, jsonb)    from public, anon;
grant  execute on function import_partners(uuid, jsonb) to authenticated;
grant  execute on function import_recruits(uuid, jsonb) to authenticated;
grant  execute on function import_tasks(uuid, jsonb)    to authenticated;

notify pgrst, 'reload schema';

-- ════════════════════════════════════════════════════════════════════════════
-- 20261019003_mc_national.sql
-- ════════════════════════════════════════════════════════════════════════════
-- Migration 042: Member Committees (MC) — the national view.
--
--   mcs               a national entity (e.g. "AIESEC in Portugal"). Has two
--                     codes: member_code (MC members join with it) and
--                     lc_code (an LCP links their LC with it).
--   mc_members        people on the MC. They are NOT members of any LC through
--                     this, so they never see an LC's tasks, chat, exchanges
--                     or wellbeing data.
--   projects.mc_id    the MC an LC belongs to, set by the LC's president.
--   mc_dashboard()    per-LC numbers for MC members: counts only (approved,
--                     realized, completed, applied this term per product, and
--                     member count). No names, no personal data, no pulse.

create table if not exists mcs (
  id          uuid primary key default gen_random_uuid(),
  name        text not null check (length(trim(name)) > 0),
  member_code text not null unique default upper(substr(md5(gen_random_uuid()::text), 1, 8)),
  lc_code     text not null unique default upper(substr(md5(gen_random_uuid()::text), 1, 8)),
  term_start  date,                                  -- national term start; default 1 February
  created_by  uuid references auth.users(id) on delete set null,
  created_at  timestamptz not null default now()
);

create table if not exists mc_members (
  mc_id     uuid not null references mcs(id) on delete cascade,
  user_id   uuid not null references auth.users(id) on delete cascade,
  role      text not null default 'member' check (role in ('mcp', 'member')),
  joined_at timestamptz not null default now(),
  primary key (mc_id, user_id)
);

alter table projects add column if not exists mc_id uuid references mcs(id) on delete set null;

create or replace function is_mc_member(p_mc_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (select 1 from mc_members where mc_id = p_mc_id and user_id = auth.uid());
$$;

create or replace function is_mcp(p_mc_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (select 1 from mc_members where mc_id = p_mc_id and user_id = auth.uid() and role = 'mcp');
$$;

alter table mcs        enable row level security;
alter table mc_members enable row level security;

-- MC members see their MC (with codes); an LC's president sees the MC their LC belongs to (name only via the view below).
drop policy if exists "mc members read their mc" on mcs;
create policy "mc members read their mc" on mcs for select using (is_mc_member(id));

drop policy if exists "mcp updates their mc" on mcs;
create policy "mcp updates their mc" on mcs for update using (is_mcp(id)) with check (is_mcp(id));

drop policy if exists "mc members see each other" on mc_members;
create policy "mc members see each other" on mc_members for select using (is_mc_member(mc_id));

drop policy if exists "mcp removes members or self leaves" on mc_members;
create policy "mcp removes members or self leaves" on mc_members for delete using (user_id = auth.uid() or is_mcp(mc_id));

-- ── Creating and joining ─────────────────────────────────────────────────────

create or replace function create_mc(p_name text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  insert into mcs (name, created_by) values (trim(p_name), auth.uid()) returning id into v_id;
  insert into mc_members (mc_id, user_id, role) values (v_id, auth.uid(), 'mcp');
  return v_id;
end;
$$;

create or replace function join_mc(p_code text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  select id into v_id from mcs where member_code = upper(trim(p_code));
  if v_id is null then raise exception 'Invalid MC code'; end if;
  insert into mc_members (mc_id, user_id) values (v_id, auth.uid()) on conflict do nothing;
  return v_id;
end;
$$;

-- The LC's president links (or, with null, unlinks) their LC.
create or replace function link_lc_to_mc(p_project_id uuid, p_lc_code text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare v_mc mcs%rowtype;
begin
  if not is_lc_president(p_project_id) then
    raise exception 'Only the LC president can link the LC to an MC';
  end if;
  if p_lc_code is null or trim(p_lc_code) = '' then
    update projects set mc_id = null where id = p_project_id;
    return null;
  end if;
  select * into v_mc from mcs where lc_code = upper(trim(p_lc_code));
  if not found then raise exception 'Invalid MC code'; end if;
  update projects set mc_id = v_mc.id where id = p_project_id;
  return v_mc.name;
end;
$$;

-- Name of the MC an LC belongs to (for the LC's settings page).
create or replace function lc_mc_name(p_project_id uuid)
returns text
language sql
security definer
stable
set search_path = public
as $$
  select m.name from projects p join mcs m on m.id = p.mc_id
  where p.id = p_project_id and auth_is_project_member(p_project_id);
$$;

-- An MC member may remove an LC from their MC.
create or replace function unlink_lc_from_mc(p_project_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from projects where id = p_project_id and mc_id is not null and is_mcp(mc_id)) then
    raise exception 'Only the MCP can remove an LC from the MC';
  end if;
  update projects set mc_id = null where id = p_project_id;
end;
$$;

-- ── National dashboard ───────────────────────────────────────────────────────

create or replace function mc_dashboard(p_mc_id uuid, p_from date default null, p_to date default null)
returns table (
  project_id uuid, lc_name text, members integer, product text,
  applied integer, approved integer, realized integer, completed integer
)
language plpgsql
security definer
stable
set search_path = public
as $$
#variable_conflict use_column
declare
  v_from date;
  v_to   date := coalesce(p_to, current_date);
begin
  if not is_mc_member(p_mc_id) then
    return;
  end if;
  select coalesce(p_from, term_start,
           case when current_date >= make_date(extract(year from current_date)::int, 2, 1)
                then make_date(extract(year from current_date)::int, 2, 1)
                else make_date(extract(year from current_date)::int - 1, 2, 1) end)
    into v_from from mcs where id = p_mc_id;

  return query
  select p.id, p.name,
         (select count(*)::int from team_members tm where tm.project_id = p.id),
         pr.code,
         (select count(*)::int from exchanges e where e.project_id = p.id and e.product = pr.code and e.applied_at   between v_from and v_to),
         (select count(*)::int from exchanges e where e.project_id = p.id and e.product = pr.code and e.approved_at  between v_from and v_to),
         (select count(*)::int from exchanges e where e.project_id = p.id and e.product = pr.code and e.realized_at  between v_from and v_to),
         (select count(*)::int from exchanges e where e.project_id = p.id and e.product = pr.code and e.completed_at between v_from and v_to)
  from projects p
  cross join unnest(array['ogv', 'ogta', 'ogte', 'igv', 'igta', 'igte']) as pr(code)
  where p.mc_id = p_mc_id
  order by p.name, pr.code;
end;
$$;

revoke execute on function create_mc(text)                     from public, anon;
revoke execute on function join_mc(text)                       from public, anon;
revoke execute on function link_lc_to_mc(uuid, text)           from public, anon;
revoke execute on function lc_mc_name(uuid)                    from public, anon;
revoke execute on function unlink_lc_from_mc(uuid)             from public, anon;
revoke execute on function mc_dashboard(uuid, date, date)      from public, anon;
grant  execute on function create_mc(text)                     to authenticated;
grant  execute on function join_mc(text)                       to authenticated;
grant  execute on function link_lc_to_mc(uuid, text)           to authenticated;
grant  execute on function lc_mc_name(uuid)                    to authenticated;
grant  execute on function unlink_lc_from_mc(uuid)             to authenticated;
grant  execute on function mc_dashboard(uuid, date, date)      to authenticated;

notify pgrst, 'reload schema';

